const GEN_EVENTS = [
  {"name": "曹彰", "title": "黄鬚児の大勝", "text": "曹彰は北の烏桓との戦いで、自ら先頭に立って馬を走らせ、敵を打ち破った。知らせを聞いた曹操は「黄色いひげの息子は、たいしたものだ」と喜んだ。", "quote": "男なら、馬に乗り大軍を率いて手柄を立てるのみ！", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "stat", "k": "lead", "v": 2}, {"t": "city", "k": "train", "v": 6}], "src": "正史・曹彰伝"},
  {"name": "曹洪", "title": "天下に洪なかるべし", "text": "戦に負けて馬を失った曹操に、曹洪は自分の馬をさし出した。「天下にこの洪がいなくてもよいが、殿がいなくてはなりません」と言い、自分は歩いて守り抜いた。", "quote": "天下に洪はなくともよい。されど殿はなくてはならぬ！", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・曹洪伝"},
  {"name": "曹純", "title": "虎豹騎を率いて", "text": "曹純は、曹操の選りすぐりの騎兵「虎豹騎」をまかされた。兵をよくいたわり、きびしく鍛えたので、虎豹騎はますます強くなった。", "quote": "虎豹騎は天下一の騎兵。一人ひとりが我が宝よ。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・曹純伝"},
  {"name": "曹休", "title": "わが家の千里の駒", "text": "遠くから苦労して駆けつけた曹休を見て、曹操は「これは我が一族の千里の駒だ」と大いに喜んだ。曹休は息子たちと同じようにかわいがられた。", "quote": "このご恩、戦場での働きで必ずお返しします。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・曹休伝"},
  {"name": "曹真", "title": "ふり向いて虎を射る", "text": "狩りの最中、曹真は虎に追いかけられた。あわてずにふり向いて矢を放つと、虎は一矢でたおれた。その勇ましさを見た曹操は、曹真に虎豹騎をまかせた。", "quote": "虎ごときに背を向けたままでは、曹家の名がすたる。", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 5}], "src": "正史・曹真伝"},
  {"name": "夏侯淵", "title": "三日で五百里", "text": "夏侯淵の軍はとても足が速く、敵が思いもしない時にあらわれた。人々は「三日で五百里、六日で千里」と言って、その速さをたたえた。", "quote": "敵が支度を終える前に、我らはもう目の前におる！", "cond": [], "fx": [{"t": "city", "k": "train", "v": 7}, {"t": "foe_city", "k": "train", "v": -5}], "src": "正史・夏侯淵伝（裴注）"},
  {"name": "夏侯覇", "title": "夏侯氏の甥", "text": "劉禅は夏侯覇をあたたかく迎え、「父上は戦の中でたおれたのだ」と語った。そして自分の子を指さし、「この子は夏侯氏の甥です」と言って、手厚くもてなした。", "quote": "なんとありがたいお言葉……この身をささげましょう。", "cond": [{"t": "with", "who": "劉禅"}], "fx": [{"t": "loyalty", "v": 25}], "src": "正史・夏侯淵伝（裴注・魏略）"},
  {"name": "于禁", "title": "まず陣を固めよ", "text": "負け戦のさなか、于禁は乱暴をはたらく味方の兵をこらしめ、まず陣を固めて敵を退けた。言いわけより先に守りを優先した姿に、曹操は「昔の名将にもまさる」とほめた。", "quote": "申し開きは後でよい。今は敵を防ぐのが先だ。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・于禁伝"},
  {"name": "楽進", "title": "いつも一番乗り", "text": "楽進は体は小さいが、とても勇ましかった。城を攻めるたびに、だれよりも先に城壁をよじのぼり、味方の兵たちを勇気づけた。", "quote": "体が小さくとも、肝っ玉は誰にも負けん！続け！", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 5}], "src": "正史・楽進伝"},
  {"name": "李典", "title": "伏兵を見抜く", "text": "逃げる劉備を追おうとする夏侯惇に、李典は「伏兵があるかもしれない」と忠告した。思ったとおり夏侯惇は伏兵にあったが、李典がかけつけて助け出した。", "quote": "敵が理由もなく退くときは、必ず何かあるものです。", "cond": [{"t": "with", "who": "夏侯惇"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "loyalty", "v": 10, "who": "夏侯惇"}], "src": "正史・李典伝"},
  {"name": "臧覇", "title": "仁義を守る", "text": "曹操にそむいた者が臧覇をたよって逃げてきた。曹操が引き渡しを求めると、臧覇は「頼ってきた者を差し出さないから、私は立っていられるのです」と断った。曹操は感心し、二人を許した。", "quote": "頼ってきた者を売るようでは、人の上には立てませぬ。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "gens_loyalty", "v": 4}], "src": "正史・臧覇伝"},
  {"name": "荀攸", "title": "東を見せて西を討つ", "text": "荀攸は、別の場所を攻めるふりをして敵の目をそらし、手うすになった所を急いで攻める策を出した。この策で味方は見事に勝ち、敵の大将顔良を討ち取った。", "quote": "敵の目を東に向けさせ、我らは西を討つのです。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "foe_city", "k": "train", "v": -6}], "src": "正史・荀攸伝"},
  {"name": "程昱", "title": "三つの城を守る", "text": "仲間が次々と敵に寝返り、国じゅうが乱れたとき、程昱は残った城の人々を説いて心を一つにさせた。こうして三つの城を守り抜き、曹操の帰る場所を残した。", "quote": "今こそ心を一つにする時。殿は必ず戻られる！", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・程昱伝"},
  {"name": "満寵", "title": "白馬を沈めて誓う", "text": "大水に囲まれて城の兵が弱気になったとき、満寵は白馬を水に沈めて、皆と城を守ることを誓った。兵たちは勇気を取りもどし、城は持ちこたえた。", "quote": "ここを捨てれば国が危うい。皆で守り抜くぞ！", "cond": [{"t": "with", "who": "曹仁"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "loyalty", "v": 10, "who": "曹仁"}], "src": "正史・満寵伝"},
  {"name": "鍾繇", "title": "関中から馬を送る", "text": "主君が大きな戦いをしているとき、鍾繇は関中の地をよく治め、たくさんの馬を前線に送りとどけた。主君は「まるで漢の蕭何のようだ」と喜んだ。", "quote": "後ろの守りはこの鍾繇におまかせください。", "cond": [], "fx": [{"t": "city", "k": "troops", "v": 2000}, {"t": "city", "k": "gold", "v": 500}], "src": "正史・鍾繇伝"},
  {"name": "劉曄", "title": "霹靂車", "text": "敵が高い櫓から矢を雨のように降らせてきた。劉曄は石を飛ばす車を作ろうと進言し、その石で櫓を次々と打ちこわした。兵たちはこれを霹靂車と呼んだ。", "quote": "矢には石で応えましょう。高い櫓など砕いてみせます。", "cond": [], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "stat", "k": "int", "v": 1}], "src": "演義第30回"},
  {"name": "蒋済", "title": "にせの手紙", "text": "孫権の大軍に城を囲まれたとき、蒋済は「大軍の助けがもうすぐ来る」というにせの手紙を、わざと敵の手に渡るようにした。孫権はこれを信じ、囲みをといて引き上げた。", "quote": "兵がなくとも、知恵があれば城は守れる。", "cond": [{"t": "foe", "who": "孫権"}], "fx": [{"t": "city", "k": "def", "v": 80}, {"t": "foe_city", "k": "loyal", "v": -5}], "src": "正史・蒋済伝"},
  {"name": "陳羣", "title": "九品官人法", "text": "陳羣は、地方ごとに人物の良さを調べて九つの等級に分け、役人に選ぶしくみを作った。こうして、すぐれた人が国に仕えやすくなった。", "quote": "人を正しく選べば、国はおのずと治まります。", "cond": [{"t": "year_ge", "y": 220}], "fx": [{"t": "recruit", "n": 2}, {"t": "gens_loyalty", "v": 3}], "src": "正史・陳羣伝"},
  {"name": "華歆", "title": "おくり物を返す", "text": "華歆が旅立つとき、見送りの人々がたくさんのおくり物をした。華歆はいったん全部受け取ったが、だれの品か印をつけておき、出発の前にすべて持ち主に返した。", "quote": "お気持ちだけで十分。旅に宝は重すぎますゆえ。", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・華歆伝（裴注）"},
  {"name": "鄧艾", "title": "毛布にくるまって", "text": "道もない険しい山を越えるとき、鄧艾は自分の体を毛布でくるみ、がけを転がりおりた。大将の決死の姿を見て、兵たちも続いて山を越えた。", "quote": "道がなければ作るまで。わしが先に下りるぞ！", "cond": [], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 6}, {"t": "foe_city", "k": "loyal", "v": -5}], "src": "正史・鄧艾伝"},
  {"name": "郝昭", "title": "陳倉を守り抜く", "text": "郝昭は小さな城で、ずっと多い敵の大軍を迎えうった。はしごには火矢、地下の穴には堀と、あらゆる攻めを打ち破り、ついに敵をあきらめさせた。", "quote": "わしは死んでもこの城を渡さぬ。何度でも来るがよい。", "cond": [{"t": "foe", "who": "諸葛亮"}], "fx": [{"t": "city", "k": "def", "v": 150}, {"t": "loyalty", "v": 10}], "src": "正史・明帝紀（裴注・魏略）"},
  {"name": "郭淮", "title": "川から離れて陣", "text": "大将を失って兵が乱れたとき、郭淮は兵をまとめ直した。そしてわざと川から離れて陣をしき、敵に「渡ってこい」と見せかけた。敵はあやしんで、川を渡ってこなかった。", "quote": "弱く見せて誘えば、敵はかえって進めぬものよ。", "cond": [], "fx": [{"t": "city", "k": "loyal", "v": 5}, {"t": "city", "k": "def", "v": 80}], "src": "正史・郭淮伝"},
  {"name": "文聘", "title": "涙の降伏", "text": "主君が国ごと降伏したとき、文聘は遅れて曹操のもとに来た。「国を守れなかったのが恥ずかしいのです」と泣く文聘を見て、曹操は「まことの忠臣だ」と心を打たれた。", "quote": "国を守れず、合わせる顔がございませんでした……", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・文聘伝"},
  {"name": "蔡瑁", "title": "水軍の訓練", "text": "蔡瑁は、船に不慣れな北の兵たちに、水の上での戦い方を一から教えこんだ。きちんと並んだ船の陣を見た敵の将は、「水軍のこつをよく知っている」とおどろいた。", "quote": "陸の兵も、鍛えれば水の上で戦えるようになる。", "cond": [], "fx": [{"t": "city", "k": "train", "v": 8}], "src": "演義第45回"},
  {"name": "張允", "title": "あらぬうたがい", "text": "敵の計略で「張允が敵と通じている」といううわさが流れた。主君にうたがいの目を向けられ、張允はすっかり気落ちしてしまった。", "quote": "私は何もしておらぬ……なぜ信じてくださらぬのだ。", "cond": [{"t": "foe", "who": "周瑜"}], "fx": [{"t": "loyalty", "v": -12}], "src": "演義第45回"},
  {"name": "楊修", "title": "絶妙好辞", "text": "石碑にきざまれた八文字のなぞを見て、楊修はすぐに「絶妙好辞（とてもすばらしい文章）」という答えを解いた。主君はしばらく考えてようやく分かり、その頭の良さにおどろいた。", "quote": "答えは簡単。絶妙好辞、すばらしい文という意味です。", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "pol", "v": 1}], "src": "演義第71回"},
  {"name": "袁譚", "title": "弟に負けてなるものか", "text": "父のあとつぎをめぐって、袁譚は弟の袁尚と争うことになった。長男の意地を見せようと、袁譚は兵を集めて、きびしく鍛え上げた。", "quote": "袁家の長男はこのわしだ。弟には負けぬ！", "cond": [{"t": "foe", "who": "袁尚"}], "fx": [{"t": "city", "k": "troops", "v": 2000}, {"t": "city", "k": "train", "v": 5}], "src": "正史・袁紹伝"},
  {"name": "袁尚", "title": "父に愛された子", "text": "袁尚は見た目がりりしく、父の袁紹にとてもかわいがられた。袁尚もその期待にこたえようと、家臣たちに親しく声をかけ、人気を集めた。", "quote": "父上の名に恥じぬよう、皆とともに励みたい。", "cond": [{"t": "lord", "who": "袁紹"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "loyalty", "v": 10}], "src": "正史・袁紹伝"},
  {"name": "袁熙", "title": "北の守り", "text": "父から幽州をまかされた袁熙は、北の地をおだやかに治めようと力をつくした。おごらずまじめな人柄に、土地の人々も少しずつ心を開いていった。", "quote": "派手な手柄はなくとも、民が安らかならそれでよい。", "cond": [], "fx": [{"t": "city", "k": "loyal", "v": 6}, {"t": "city", "k": "food", "v": 3000}], "src": "経歴にもとづく創作（正史・袁紹伝：幽州刺史）"},
  {"name": "顔良", "title": "河北一の猛将", "text": "顔良は戦場に出ると、名のある敵将を次々に討ち取り、助けに来た徐晃も打ち負かした。敵の陣は大さわぎになり、だれも顔良の前に出ようとしなくなった。", "quote": "河北の顔良とはわしのこと！次に死にたい者は誰だ！", "cond": [{"t": "foe", "who": "曹操"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -6}], "src": "演義第25回"},
  {"name": "文醜", "title": "二将を退ける", "text": "追ってきた張遼に、文醜はふり向きざまに矢を放ち、張遼の馬に命中させた。続いて立ちはだかった徐晃とも戦い、追い返してしまった。", "quote": "顔良のかたきを討つ！わしの前に立つ者は皆たおす！", "cond": [{"t": "foe", "who": "曹操"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 5}, {"t": "foe_city", "k": "train", "v": -5}], "src": "演義第26回"},
  {"name": "田豊", "title": "今こそ許を討て", "text": "曹操が東の劉備を攻めに出て、本拠の守りがうすくなった。田豊はそのすきをついて攻めこむよう、強く主君にすすめた。", "quote": "敵の留守をつくのは今しかありませぬ。迷えば好機は二度と来ませぬぞ。", "cond": [{"t": "foe", "who": "曹操"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "foe_city", "k": "loyal", "v": -6}], "src": "正史・袁紹伝"},
  {"name": "沮授", "title": "天子をお迎えせよ", "text": "都があれて、天子は行き場を失っていた。沮授は、天子をお迎えして国の柱となれば、天下の人々の心が集まると主君に説いた。", "quote": "天子を守り、正しい道で天下をまとめる。これこそ大きな計です。", "cond": [{"t": "year_ge", "y": 195}], "fx": [{"t": "stat", "k": "cha", "v": 1, "who": "lord"}, {"t": "all", "k": "loyal", "v": 5}], "src": "正史・袁紹伝注『献帝伝』"},
  {"name": "審配", "title": "わが君は北に", "text": "鄴の城を守る審配は、敵にかこまれても最後まで降参しなかった。そのまっすぐな心に、城の兵たちも心をひとつにした。", "quote": "わが君は北におられる。この審配、背を向けることはせぬ。", "cond": [{"t": "owns", "city": "鄴"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "loyalty", "v": 15}], "src": "正史・袁紹伝"},
  {"name": "逢紀", "title": "冀州を手に入れる策", "text": "逢紀は、となりの国の主の気の弱さを見ぬいていた。外から強い軍でおどせば、自分から国をゆずるだろうと主君に策をさずけた。", "quote": "臆病な者は、こわがらせれば自分から道をあけるものです。", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "foe_city", "k": "loyal", "v": -5}], "src": "正史・袁紹伝注／後漢書・袁紹伝"},
  {"name": "許攸", "title": "聞き入れられぬ策", "text": "許攸は、身軽な兵で敵の本拠をつく策を出したが、主君は聞き入れなかった。じまんの知恵を軽く見られた許攸は、不満をつのらせた。", "quote": "わしの策を用いぬとは。この主君の先は見えたわ。", "cond": [], "fx": [{"t": "loyalty", "v": -12}, {"t": "stat", "k": "int", "v": 1}], "src": "演義第30回"},
  {"name": "高覧", "title": "張郃と並んで", "text": "高覧は張郃と力を合わせ、敵の陣へ攻めかかった。息の合った二人の働きに、兵たちも勇気づけられた。", "quote": "張郃どの、ともに行こうぞ。背中はこの高覧があずかった。", "cond": [{"t": "with", "who": "張郃"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "正史・張郃伝"},
  {"name": "麴義", "title": "界橋の大盾", "text": "麴義は盾と弩の兵を地にふせさせ、白馬の騎兵が目の前まで来たところで一斉に立たせて射かけた。名高い騎兵は大きくくずれた。", "quote": "あわてるな。十分に引きつけてから射よ！", "cond": [], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 8}], "src": "正史・袁紹伝注『英雄記』"},
  {"name": "淳于瓊", "title": "油断の酒", "text": "兵糧の守りをまかされた淳于瓊は、敵は来るまいと酒をあおってしまった。守りがゆるみ、兵たちの気持ちもたるんでしまった。", "quote": "はっはっは、こんな所まで攻めてくる者などおらぬわ。", "cond": [], "fx": [{"t": "city", "k": "train", "v": -5}, {"t": "city", "k": "food", "v": -2000}], "src": "演義第30回"},
  {"name": "郭図", "title": "張郃へのそしり", "text": "自分の策が外れたことをはずかしく思った郭図は、責任を張郃にかぶせようと悪いうわさを広めた。張郃の心は主君からはなれていった。", "quote": "負けたのは張郃が本気で戦わなかったからにございます。", "cond": [{"t": "with", "who": "張郃"}], "fx": [{"t": "loyalty", "v": -12, "who": "張郃"}], "src": "正史・張郃伝"},
  {"name": "高幹", "title": "国をゆずらせる使者", "text": "高幹は使者となり、となりの国の主のもとへ出かけた。おだやかに道理を説き、戦わずに相手の心を動かした。", "quote": "争って民を苦しめるより、手を取るほうがよろしいでしょう。", "cond": [{"t": "lord", "who": "袁紹"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "foe_city", "k": "loyal", "v": -6}], "src": "正史・袁紹伝"},
  {"name": "紀霊", "title": "轅門射戟", "text": "劉備を攻めに来た紀霊の前で、呂布は遠くに立てた戟を一矢で射ぬいた。おどろいた紀霊は、その日は兵を引いた。", "quote": "なんという腕前…。これでは天の意にそむくわけにもいかぬ。", "cond": [{"t": "foe", "who": "呂布"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "loyal", "v": 4}], "src": "正史・呂布伝／演義第16回"},
  {"name": "韓当", "title": "三代に仕える古強者", "text": "韓当は孫堅のころから孫家に仕えてきた古い武将だ。若い兵たちに馬と弓をていねいに教え、軍はひきしまった。", "quote": "わしは三代の殿にお仕えしてきた。おぬしらも胸を張れ。", "cond": [], "fx": [{"t": "city", "k": "train", "v": 7}, {"t": "loyalty", "v": 10}], "src": "正史・韓当伝（経歴にもとづく創作）"},
  {"name": "周泰", "title": "傷あとの数だけ", "text": "周泰が身分の低い出だと、ほかの将たちが従わなかった。主君は宴で周泰に服をぬがせ、体じゅうの傷のわけを一つずつ語らせた。将たちはみな頭を下げた。", "quote": "この傷はすべて、殿をお守りした時のものでございます。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "gens_loyalty", "v": 5}], "src": "正史・周泰伝注『江表伝』"},
  {"name": "蒋欽", "title": "うらみを忘れて", "text": "徐盛は、以前に蒋欽の部下を罰したことがあり、仕返しをおそれていた。ところが蒋欽は、いつも徐盛の良いところをほめた。人々は蒋欽の心の広さに感心した。", "quote": "国のための人材をほめるのに、昔のことなど関係ありますまい。", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "gens_loyalty", "v": 4}], "src": "正史・蒋欽伝"},
  {"name": "凌統", "title": "仇との和解", "text": "父の仇の甘寧をうらみ続けていた凌統。戦場で危ないところを甘寧の矢に救われ、ついに心のわだかまりをといた。", "quote": "命の恩は、うらみよりも重い。甘寧どの、これからは友だ。", "cond": [{"t": "with", "who": "甘寧"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "loyalty", "v": 10, "who": "甘寧"}, {"t": "stat", "k": "cha", "v": 1}], "src": "演義第68回"},
  {"name": "徐盛", "title": "にせの城壁", "text": "敵の大軍が攻めてきた時、徐盛は木と布で長い城壁を作り、川辺に見せかけの守りを並べた。見た敵はおどろき、攻めずに引きあげた。", "quote": "本物の壁などいらぬ。敵の目に見えればそれでよい。", "cond": [], "fx": [{"t": "city", "k": "def", "v": 130}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・徐盛伝"},
  {"name": "丁奉", "title": "雪の中の短兵", "text": "雪の日、丁奉は兵によろいをぬがせ、刀だけを持たせて敵陣へ駆けあがった。油断していた敵は大さわぎになり、くずれ去った。", "quote": "よろいなど重いだけだ！身軽になって一気にかかれ！", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 8}], "src": "正史・丁奉伝"},
  {"name": "張紘", "title": "秣陵に都を", "text": "張紘は、川と山に守られた秣陵の地こそ、本拠にふさわしいと主君にすすめた。町づくりが進み、人々も集まってきた。", "quote": "この地は守りやすく、人も物も集まります。都とすべきです。", "cond": [{"t": "owns", "city": "建業"}], "fx": [{"t": "pct", "k": "comm", "v": 5}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・張紘伝注『江表伝』"},
  {"name": "諸葛瑾", "title": "そむかぬ二人", "text": "弟が敵国にいる諸葛瑾が、敵と通じているといううわさが立った。主君は笑ってとりあわず、諸葛瑾を変わらず信じた。", "quote": "わが主君の信に、命をかけて応えるのみです。", "cond": [{"t": "foe", "who": "諸葛亮"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "cha", "v": 1, "who": "lord"}], "src": "正史・諸葛瑾伝"},
  {"name": "朱然", "title": "江陵を守りぬく", "text": "大軍にかこまれ、城の兵は病でへっていた。それでも朱然は落ちついて兵をはげまし、すきを見て敵の陣を打ちやぶり、城を守りぬいた。", "quote": "あわてることはない。城がある限り、われらは負けぬ。", "cond": [{"t": "owns", "city": "江陵"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・朱然伝"},
  {"name": "朱桓", "title": "勝負は将にあり", "text": "敵の大軍が来ると聞き、兵たちはおびえた。朱桓は「勝ち負けは数でなく将で決まる」とはげまし、少ない兵で敵を打ち返した。", "quote": "勝負は将にあり、兵の数ではない！わしについて来い！", "cond": [], "fx": [{"t": "city", "k": "train", "v": 7}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・朱桓伝"},
  {"name": "潘璋", "title": "市場の兵集め", "text": "潘璋は町の市場をまわって人に声をかけ、あっという間に百人あまりの兵を集めた。その手ぎわに主君も目を見はった。", "quote": "腕に自信のある者は来い！手柄を立てればたっぷり報いるぞ！", "cond": [], "fx": [{"t": "city", "k": "troops", "v": 2000}, {"t": "loyalty", "v": 8}], "src": "正史・潘璋伝"},
  {"name": "顧雍", "title": "顧公がいると", "text": "顧雍は酒を飲まず、言葉も少ない人だった。宴に顧雍がいると、みんな気がひきしまり、羽目を外す者はいなかった。政治もきちんと行われた。", "quote": "国のことを話すのに、酒の勢いはいりませぬ。", "cond": [], "fx": [{"t": "all", "k": "loyal", "v": 5}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・顧雍伝"},
  {"name": "虞翻", "title": "筆で城を開く", "text": "虞翻は敵の城を守る将に手紙を書き、むだな戦いをやめるよう道理を説いた。手紙を読んだ相手の心は大きくゆらいだ。", "quote": "わしの筆は剣よりよく切れる。読めば分かるはずだ。", "cond": [], "fx": [{"t": "foe_city", "k": "loyal", "v": -8}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・虞翻伝注『呉書』"},
  {"name": "闞沢", "title": "書き写して学ぶ", "text": "家がまずしかった闞沢は、人にたのまれて本を書き写し、紙と筆のお金をかせいだ。写し終えるころには中身をすっかり覚えていた。", "quote": "一冊写せば一冊覚える。まずしさは学びのさまたげになりませぬ。", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・闞沢伝"},
  {"name": "呂範", "title": "まっすぐなお金の番", "text": "お金の管理をまかされた呂範は、若い主君から内緒でお金をたのまれても、一人では決めずきちんと上に届け出た。後に主君はその正しさを深く信じた。", "quote": "お金のことはすべて記してあります。私の勝手にはできませぬ。", "cond": [], "fx": [{"t": "city", "k": "gold", "v": 600}, {"t": "loyalty", "v": 10}], "src": "正史・呂範伝"},
  {"name": "馬岱", "title": "西涼の騎兵", "text": "馬岱はいとこの馬超とともに、西涼の騎兵をきたえた。風のように走る馬の群れに、町の人々も目を見はった。", "quote": "兄上、西涼の騎兵の力、思う存分見せてやりましょう。", "cond": [{"t": "with", "who": "馬超"}], "fx": [{"t": "city", "k": "train", "v": 7}, {"t": "loyalty", "v": 8}], "src": "正史・馬超伝（経歴にもとづく創作）"},
  {"name": "関平", "title": "父を守る一騎打ち", "text": "強い敵将が関羽に一騎打ちをいどんできた。関平は父の身を案じ、先に飛び出して勇ましく戦った。", "quote": "父上が出るまでもありませぬ。まずはこの関平がお相手する！", "cond": [{"t": "with", "who": "関羽"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "loyalty", "v": 10}], "src": "演義第74回"},
  {"name": "関興", "title": "青龍刀を取り戻す", "text": "関興は父の形見である青龍偃月刀を取り戻した。父の刀を手にした関興は、いっそう勇ましく戦うようになった。", "quote": "父上の刀、たしかに取り戻しました。この刀に恥じぬ働きをいたします。", "cond": [{"t": "year_ge", "y": 220}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "loyalty", "v": 10}], "src": "演義第83回"},
  {"name": "張苞", "title": "義兄弟の誓い", "text": "先陣を争って腕くらべをした張苞と関興。二人の父のように、兄弟となって力を合わせよと言われ、二人はその場で誓いを立てた。", "quote": "関興、今日からはおぬしが弟だ！ともに父上たちの名を上げようぞ！", "cond": [{"t": "with", "who": "関興"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "loyalty", "v": 10, "who": "関興"}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第81回"},
  {"name": "劉封", "title": "上庸攻め", "text": "劉封は大軍をひきいて山道をこえ、上庸の地へ攻め入った。その地の守将たちは次々と降り、劉封の名は高まった。", "quote": "養父上の名を、この劉封の手で天下に広めてみせる！", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "troops", "v": 2000}], "src": "正史・劉封伝"},
  {"name": "糜芳", "title": "守りの心のゆらぎ", "text": "留守を守る糜芳は、蔵の火事で大切な物資を失い、きびしく叱られることをおそれた。心はしだいに主君から離れていった。", "quote": "叱られるくらいなら……いや、なんでもない。", "cond": [{"t": "year_ge", "y": 215}], "fx": [{"t": "loyalty", "v": -15}, {"t": "city", "k": "food", "v": -2000}], "src": "正史・関羽伝（江陵の火事で物資を失い関羽を恐れた）"},
  {"name": "周倉", "title": "大刀を担ぐ男", "text": "周倉は関羽にほれこみ、そばを離れずに仕えた。いつも関羽の大きな刀を肩に担ぎ、どこまでもついて行った。", "quote": "この周倉、死ぬまで将軍のおそばにおります！", "cond": [{"t": "with", "who": "関羽"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第28回（関羽に従う）"},
  {"name": "馬謖", "title": "心を攻めよ", "text": "南への出兵の前、馬謖は「城を攻めるより人の心を攻めるのがよい」と進言した。その言葉どおり、人々を力でなく心でしたがわせる方針が決まった。", "quote": "城を攻めるは下、心を攻めるが上でございます。", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "all", "k": "loyal", "v": 5}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・馬良伝注『襄陽記』（攻心為上）"},
  {"name": "蒋琬", "title": "国を背負う器", "text": "町の長だった蒋琬は、仕事をせず酒に酔っていると見られ、罰せられかけた。だが諸葛亮が「この人は国を支える器だ」とかばい、蒋琬は大きな仕事をまかされた。", "quote": "小さな町では、私の力を出しきれなかったのです。", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "stat", "k": "pol", "v": 2}, {"t": "loyalty", "v": 15}], "src": "正史・蒋琬伝（社稷之器）"},
  {"name": "費禕", "title": "碁を打つ余裕", "text": "敵の大軍がせまる中、出陣の前に費禕は落ち着いて碁を打っていた。見送りの者は、その様子を見て「この人なら必ず勝つ」と安心した。", "quote": "あわてても碁石は動きませぬ。さあ、もう一局。", "cond": [{"t": "year_ge", "y": 230}], "fx": [{"t": "all", "k": "train", "v": 5}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・費禕伝（来敏と囲碁、興勢の役）"},
  {"name": "董允", "title": "きびしい忠言", "text": "董允は、主君が楽しみばかりを増やそうとするたびに、正しい道理を説いていさめた。わがままを言う家臣たちも、董允をおそれて悪いことができなかった。", "quote": "殿、国のためにこそ、ここはおこらえくだされ。", "cond": [], "fx": [{"t": "all", "k": "loyal", "v": 4}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・董允伝（劉禅をいさめ黄皓を抑えた）"},
  {"name": "伊籍", "title": "とんちの使者", "text": "使者として呉へ行った伊籍に、孫権が「道理のない君主に仕えて苦労するな」とからかった。伊籍は「一度おじぎをするくらい、苦労ではありません」と見事に返し、孫権を感心させた。", "quote": "一度おじぎをするくらい、苦労のうちに入りませぬ。", "cond": [{"t": "foe", "who": "孫権"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "city", "k": "gold", "v": 400}], "src": "正史・伊籍伝"},
  {"name": "王平", "title": "十字の名将", "text": "王平は字を十ほどしか知らなかったが、山や川の形をよく見て、陣を固く守った。仲間が負けた時も、王平の軍だけは落ち着いて引き上げた。", "quote": "字は読めずとも、地の形は読めまする。", "cond": [{"t": "year_ge", "y": 220}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・王平伝（街亭、識字十字）"},
  {"name": "廖化", "title": "死んだふりの帰参", "text": "敵に囲まれて捕らえられた廖化は、死んだふりをして見張りをだまし、年老いた母を連れて抜け出した。そして昔の主君のもとへ戻ってきた。", "quote": "どれほど遠くとも、殿のもとへ帰ってまいりました。", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "loyalty", "v": 25}, {"t": "gens_loyalty", "v": 3}], "src": "正史・宗預伝付廖化伝（偽死して劉備に帰す）"},
  {"name": "厳顔", "title": "断頭将軍", "text": "捕らえられた厳顔は「首を切られる将軍はいても、降る将軍はいない」と言いはなった。その堂々とした姿に、敵の将も縄をとき、客としてもてなした。", "quote": "首を切るならさっさと切れ。なぜ怒るのか！", "cond": [{"t": "foe", "who": "張飛"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "loyalty", "v": 15}], "src": "正史・張飛伝（断頭将軍）"},
  {"name": "呉懿", "title": "縁をむすぶ家", "text": "呉懿の妹は、のちに君主の妃となった。呉懿の一族は主君と深い縁でむすばれ、家臣たちの結びつきも強くなった。", "quote": "妹の縁、わが家の誇りとして殿をお支えいたす。", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "gens_loyalty", "v": 4}], "src": "正史・穆皇后伝・呉壹伝（妹が劉備の皇后）"},
  {"name": "馬忠", "title": "失って得た宝", "text": "大切な家臣を失って落ちこんでいた主君は、馬忠と話して元気を取り戻した。「一人を失ったが、また一人の賢い者を得た」と喜んだ。", "quote": "非才ながら、殿のお力になりとうございます。", "cond": [{"t": "lord", "who": "劉備"}, {"t": "year_ge", "y": 222}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "cha", "v": 1, "who": "lord"}], "src": "正史・馬忠伝（黄権を失い狐篤を得る）"},
  {"name": "劉琦", "title": "はしごを外して", "text": "命をねらわれておびえる劉琦は、諸葛亮を二階へ招き、はしごを外して知恵を求めた。教えにしたがって遠くの江夏へ移り、身を守った。", "quote": "天にも地にも届かぬここなら、話してくださろう。", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "loyalty", "v": 15}], "src": "正史・諸葛亮伝（上屋抽梯）"},
  {"name": "劉琮", "title": "戦わずの決断", "text": "大軍がせまると、劉琮は家臣たちの意見を聞いて戦わずに城をゆずる道を選んだ。民は戦に巻きこまれずにすんだが、劉琮の名は軽く見られた。", "quote": "戦えば民が苦しむ……私には、とても無理だ。", "cond": [{"t": "cities_le", "n": 3}], "fx": [{"t": "city", "k": "loyal", "v": 6}, {"t": "stat", "k": "cha", "v": -1}], "src": "正史・劉表伝（曹操に降伏）"},
  {"name": "蒯越", "title": "荊州を鎮める策", "text": "荊州が荒れていた時、蒯越は「乱れた世では、まず知恵と策を使うべきです」と説いた。悪さをする頭目たちを招いてこらしめると、土地は落ち着き、人々がしたがうようになった。", "quote": "平らな世は仁義で、乱れた世は策で治めるのです。", "cond": [{"t": "owns", "city": "襄陽"}], "fx": [{"t": "all", "k": "loyal", "v": 5}, {"t": "pct", "k": "farm", "v": 4}], "src": "正史・劉表伝注『司馬彪戦略』（宗賊の頭目を誘い出して討つ）"},
  {"name": "蒯良", "title": "仁と義の政", "text": "蒯良は「民がしたがわないのは、仁が足りないからです」と主君にすすめた。やさしい政治で、荊州の人々の心はまとまっていった。", "quote": "力で押さえる国は長くもちませぬ。", "cond": [{"t": "owns", "city": "襄陽"}], "fx": [{"t": "city", "k": "loyal", "v": 8}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・劉表伝注『司馬彪戦略』（衆不附者仁不足也）"},
  {"name": "黄祖", "title": "江夏の水の守り", "text": "黄祖は江夏を長く守り、川に船を並べて敵の水軍を何度も防いだ。強い敵が攻めてきても、江夏はなかなか落ちなかった。", "quote": "この江夏の川、たやすく渡らせはせんぞ！", "cond": [{"t": "owns", "city": "江夏"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "city", "k": "train", "v": 5}], "src": "正史・孫破虜伝・甘寧伝（江夏を守る）"},
  {"name": "陳応", "title": "飛叉の名手", "text": "陳応は二本の飛叉を自在にあやつる猛者だった。主君の前で腕前を見せると、兵たちはその勇ましさにわき立った。", "quote": "この飛叉、どんな敵でも落としてみせるわ！", "cond": [{"t": "owns", "city": "桂陽"}], "fx": [{"t": "city", "k": "train", "v": 6}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第52回（飛叉を使う桂陽の将）"},
  {"name": "張任", "title": "二君に仕えず", "text": "捕らえられた張任は、どれほど降るようすすめられても首をたてにふらなかった。「年老いた臣は二人の主には仕えない」と言い、その忠義は敵までも感心させた。", "quote": "老臣は、決して二人の主には仕えませぬ。", "cond": [{"t": "lord", "who": "劉璋"}], "fx": [{"t": "loyalty", "v": 30}, {"t": "gens_loyalty", "v": 4}], "src": "正史・劉二牧伝注『益部耆旧伝』"},
  {"name": "孟達", "title": "ゆれる心", "text": "まわりの将とうまくいかず、孟達は主君に疑われているのではと不安になった。別の勢力から届いた手紙に、心が動きはじめた。", "quote": "ここにいて、わしの身は安全なのだろうか……。", "cond": [{"t": "year_ge", "y": 215}], "fx": [{"t": "loyalty", "v": -20}], "src": "正史・劉封伝（劉封と不和、魏に降る）"},
  {"name": "冷苞", "title": "雒城の守り手", "text": "冷苞は仲間と力を合わせ、雒城への道に陣をしいて敵を待ちかまえた。兵たちは冷苞のもとで守りを固めた。", "quote": "ここを抜かれては成都が危うい。一歩も引くな！", "cond": [{"t": "lord", "who": "劉璋"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "city", "k": "train", "v": 4}], "src": "正史・劉二牧伝（涪で劉備を防ぐ）"},
  {"name": "鄧賢", "title": "陣を固める", "text": "鄧賢は冷苞とともに陣を張り、攻めてくる敵をむかえうつ準備をした。そろって働く二人の姿に、兵の士気も上がった。", "quote": "冷苞どの、背中は任せたぞ！", "cond": [{"t": "with", "who": "冷苞"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・劉二牧伝（劉璋の将として劉備を防ぐ）"},
  {"name": "譙周", "title": "笑われた学者", "text": "初めて諸葛亮に会った時、譙周の変わった様子に皆が笑った。しかし諸葛亮は「私でさえこらえられないのだから仕方ない」と言い、その深い学問を重く用いた。", "quote": "見た目は笑われても、学問は笑わせませぬ。", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "city", "k": "loyal", "v": 4}], "src": "正史・譙周伝注『蜀記』"},
  {"name": "張衛", "title": "陽平関の守り", "text": "兄の国を守るため、張衛は陽平関に兵を集め、山にそって長い守りの壁を築いた。攻める軍はなかなか先へ進めなかった。", "quote": "漢中へは一歩も入れさせぬぞ！", "cond": [{"t": "owns", "city": "漢中"}], "fx": [{"t": "city", "k": "def", "v": 130}, {"t": "city", "k": "troops", "v": 2000}], "src": "正史・張魯伝（陽平関で曹操を防ぐ）"},
  {"name": "閻圃", "title": "王を名乗るなかれ", "text": "主君に「王を名乗りましょう」という声が上がった時、閻圃はとめた。「今のままで十分豊か。名乗れば災いをまねきます」との言葉に、主君はうなずいた。", "quote": "高い名は、高い所から落ちる元にございます。", "cond": [{"t": "lord", "who": "張魯"}], "fx": [{"t": "all", "k": "loyal", "v": 4}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・張魯伝（称王をいさめる）"},
  {"name": "閻行", "title": "馬超を刺す", "text": "戦いの中で閻行は馬超と一騎打ちとなり、ほこで馬超を刺した。ほこが折れると、その柄で打ちすえるほどの勇ましさだった。", "quote": "錦馬超とて、恐れるに足らん！", "cond": [{"t": "foe", "who": "馬超"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 5}], "src": "正史・張既伝注『魏略』"},
  {"name": "李儒", "title": "影の知恵袋", "text": "李儒は主君のそばで、だれも思いつかない策を次々とささやいた。その知恵で主君の力は増したが、人々は李儒をおそれた。", "quote": "わが策を用いれば、天下も思いのまま。", "cond": [{"t": "lord", "who": "董卓"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "city", "k": "gold", "v": 600}], "src": "演義第3〜9回（董卓の参謀）"},
  {"name": "郭汜", "title": "仲間われ", "text": "郭汜の妻は、夫が李傕の家に出入りするのをきらい、二人の仲を悪くしようとした。疑いが広がり、仲間どうしで兵を向け合うことになった。", "quote": "李傕め、わしを毒で殺す気か！", "cond": [{"t": "with", "who": "李傕"}], "fx": [{"t": "loyalty", "v": -15}, {"t": "city", "k": "loyal", "v": -6}], "src": "正史・董卓伝注『典略』（妻の嫉妬で李傕と不和）"},
  {"name": "張済", "title": "ひもじい兵のため", "text": "兵たちの食べ物が足りなくなり、張済は軍を連れて食料のある土地へと移った。兵たちは張済の気づかいに感謝した。", "quote": "腹が減っては戦えぬ。皆、ついてまいれ。", "cond": [], "fx": [{"t": "city", "k": "food", "v": 4000}, {"t": "loyalty", "v": 10}], "src": "正史・董卓伝（軍の飢えで南陽へ向かう）"},
  {"name": "樊稠", "title": "同郷の情け", "text": "戦いで韓遂を追いつめた樊稠は、同郷のよしみで馬を並べて語り合い、そのまま見のがした。このことで、仲間の李傕に疑われてしまった。", "quote": "同じ郷の者を、どうして討てようか。", "cond": [{"t": "with", "who": "李傕"}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "loyalty", "v": -12}], "src": "正史・董卓伝注『九州春秋』"},
  {"name": "華雄", "title": "赤いずきん", "text": "華雄は孫堅の軍を打ち破り、逃げる孫堅の赤いずきんを追った。だがそれは家来の祖茂のしわざで、華雄は祖茂を討ち取り勇名をとどろかせた。", "quote": "われこそ華雄！かかってくる者はおらんのか！", "cond": [{"t": "foe", "who": "孫堅"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "演義第5回（祖茂を討つ）"},
  {"name": "徐栄", "title": "汴水の待ちぶせ", "text": "董卓をたおそうと追ってきた曹操の軍を、徐栄は汴水のほとりで待ちかまえた。ねばり強く戦って敵を打ち負かし、曹操はあやうく命を落としかけた。", "quote": "勢いだけで来る敵など、待てば勝てる。", "cond": [{"t": "lord", "who": "董卓"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "正史・武帝紀（汴水の戦い）"},
  {"name": "牛輔", "title": "うらないに頼る", "text": "董卓のむすめむこの牛輔は、こわがりで、いつもうらない師に吉か凶かを聞いてから人に会った。あまりのびくびくぶりに、兵たちの心はしだいにはなれていった。", "quote": "き、今日は会ってもよい日か？先に占ってくれ！", "cond": [{"t": "with", "who": "董卓"}], "fx": [{"t": "city", "k": "train", "v": -5}, {"t": "loyalty", "v": -10}], "src": "正史・董卓伝 裴注『魏書』"},
  {"name": "陳登", "title": "田畑をうるおす", "text": "陳登は土地をくまなく見て回り、水路をほって田んぼに水を引いた。お米がたくさん取れるようになり、民はゆたかになった。", "quote": "民がおなかいっぱいなら、国はゆらがぬ。", "cond": [], "fx": [{"t": "pct", "k": "farm", "v": 5}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・呂布伝 裴注『先賢行状』"},
  {"name": "陳珪", "title": "縁談をこわす", "text": "袁術が呂布のむすめを息子のよめにほしいと言ってきた。陳珪は「袁術と手を組めば天下の敵になります」と呂布を説き、話を取りやめさせた。", "quote": "天子にそむく者と結んでは、ともに沈むだけですぞ。", "cond": [{"t": "with", "who": "呂布"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "pol", "v": 1, "who": "lord"}], "src": "正史・呂布伝"},
  {"name": "公孫続", "title": "黒山への使い", "text": "父の公孫瓚が追いつめられると、公孫続は黒山の張燕たちのもとへ助けを求めに行った。むずかしい役目をはたし、味方の兵が集まってきた。", "quote": "父上のため、どんな山道でもこえてみせます！", "cond": [{"t": "lord", "who": "公孫瓚"}], "fx": [{"t": "city", "k": "troops", "v": 2000}, {"t": "loyalty", "v": 10}], "src": "正史・公孫瓚伝"},
  {"name": "公孫淵", "title": "燕王を名のる", "text": "公孫淵は遼東で力をたくわえ、ついに自分を燕王と名のった。まわりの大国の顔色をうかがいながら、天下をねらう野心をむき出しにした。", "quote": "遼東はわしの国だ。だれの指図も受けぬ！", "cond": [{"t": "owns", "city": "襄平"}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "all", "k": "train", "v": 4}], "src": "正史・公孫度伝付公孫淵伝"},
  {"name": "皇甫嵩", "title": "長社の火計", "text": "黄巾の大軍が、草むらの近くに陣をはった。風の強い夜、皇甫嵩は兵に火をつけさせ、炎にまぎれて打って出て、敵をさんざんに打ち破った。", "quote": "風がわれらに味方した。いまこそ打って出よ！", "cond": [], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "foe_city", "k": "train", "v": -6}], "src": "正史（後漢書）皇甫嵩伝 / 演義第1回"},
  {"name": "朱儁", "title": "宛の城ぜめ", "text": "宛にこもった黄巾は、降参を申し出た。朱儁はゆるさず、わざと囲みの一方をあけて敵をさそい出し、そこを打ってついに城をうばい取った。", "quote": "逃げ道を見せれば、敵は戦う気をなくすものよ。", "cond": [], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "def", "v": 100}], "src": "正史（後漢書）朱儁伝 / 演義第2回"},
  {"name": "盧植", "title": "教え子たち", "text": "大学者の盧植のもとには、多くの若者が学びに来ていた。そのうちのひとりが、のちの劉備である。教え子のうわさを聞きつけて、新しい人材がたずねてきた。", "quote": "学ぶ心がある者は、いつでも来るがよい。", "cond": [], "fx": [{"t": "recruit", "n": 1}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・先主伝"},
  {"name": "董承", "title": "衣帯の密詔", "text": "董承は、天子から帯にぬいこまれたひみつの命令を受け取った。「天子をないがしろにする者をたおせ」。董承はなみだを流し、命をかけてやりとげるとちかった。", "quote": "陛下のお心、この董承がたしかにお受けしました。", "cond": [{"t": "year_ge", "y": 196}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・先主伝 / 演義第20回"},
  {"name": "劉辟", "title": "汝南の出むかえ", "text": "汝南にいた劉辟は、劉備と力を合わせて許のあたりを荒らし回った。劉備をあたたかくむかえ、ともに戦う仲間となった。", "quote": "劉備どの、汝南はあんたの味方だぜ！", "cond": [{"t": "with", "who": "劉備"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "loyalty", "v": 5, "who": "劉備"}], "src": "正史・先主伝"},
  {"name": "曹昂", "title": "父に馬を", "text": "宛で敵の夜討ちを受け、曹操の馬が矢に当たってたおれた。曹昂はすぐに自分の馬を父にゆずり、自分は後に残って戦った。", "quote": "父上、この馬でお逃げください！ここはわたしが！", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "loyalty", "v": 10, "who": "lord"}], "src": "正史・武帝紀 裴注『魏書』『世語』"},
  {"name": "李通", "title": "使者を切る", "text": "袁紹と劉表が、それぞれ李通に味方になれとさそってきた。まわりの者はなびこうと言ったが、李通は袁紹の使者を切りすて、曹操への心をつらぬいた。", "quote": "曹公はかならず天下をまとめる。わしはうらぎらぬ。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・李通伝"},
  {"name": "辛毗", "title": "すそを引く", "text": "曹丕が、たくさんの民を無理に引っこしさせようとした。辛毗は反対し、席を立つ曹丕の着物のすそをつかんではなさず、思いとどまらせた。", "quote": "民を苦しめる命令だけは、お受けできませぬ！", "cond": [{"t": "with", "who": "曹丕"}], "fx": [{"t": "all", "k": "loyal", "v": 5}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・辛毗伝"},
  {"name": "崔琰", "title": "堂々たる答え", "text": "曹操がひそかにあとつぎをだれにするか家臣にたずねた。ほかの人がこっそり答える中、崔琰だけはみんなに見える形で、正しい長男をあとつぎにすべきだと答えた。", "quote": "正しい道を言うのに、かくす必要はありませぬ。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "gens_loyalty", "v": 4}], "src": "正史・崔琰伝"},
  {"name": "毛玠", "title": "天子を奉じて", "text": "毛玠は曹操に、天子を大切にささえて命令を出すこと、そして田畑をたがやし、兵糧をたくわえることを説いた。曹操はこの考えを大いに気に入った。", "quote": "天子を立て、田をたがやせば、天下は自然に従います。", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "pct", "k": "farm", "v": 5}, {"t": "all", "k": "food", "v": 2000}], "src": "正史・毛玠伝"},
  {"name": "張既", "title": "馬騰を説く", "text": "曹操は、関中の馬騰を都に来させたかった。張既は馬騰をたずねて説き、ぐずぐずする馬騰のために道すじの出むかえまで整えて、とうとう東へ向かわせた。", "quote": "都でのお役目、きっとご一族の名をあげますぞ。", "cond": [], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・張既伝"},
  {"name": "賈逵", "title": "賈侯渠", "text": "豫州をおさめた賈逵は、川をせきとめて長い水路をつくり、船で物を運べるようにした。人々はこの水路を「賈侯渠」とよんで、たたえた。", "quote": "水の道ができれば、田も町も生き返る。", "cond": [], "fx": [{"t": "pct", "k": "farm", "v": 4}, {"t": "pct", "k": "comm", "v": 4}], "src": "正史・賈逵伝"},
  {"name": "夏侯尚", "title": "上庸を取る", "text": "孟達が魏に降ると、夏侯尚は徐晃とともに上庸へ兵を進め、劉封を追いはらった。曹丕は親友の手がらを大いによろこんだ。", "quote": "上庸は落ちた。陛下に吉報をお届けせよ！", "cond": [{"t": "year_ge", "y": 220}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "loyalty", "v": 10}], "src": "正史・夏侯尚伝 / 劉封伝"},
  {"name": "曹爽", "title": "興勢の失敗", "text": "手がらを立てたい曹爽は、大軍で蜀にせめこんだ。けわしい山道で食料が運べず、蜀軍にもはばまれて、多くの兵や牛馬を失って引き返すことになった。", "quote": "な、なぜだ…わしの大軍がなぜ進めぬのだ！", "cond": [{"t": "year_ge", "y": 240}], "fx": [{"t": "city", "k": "troops", "v": -2000}, {"t": "city", "k": "train", "v": -6}], "src": "正史・曹爽伝"},
  {"name": "鍾会", "title": "今の張良", "text": "寿春のいくさで、鍾会はつぎつぎと作戦を考え、勝利に大きく役立った。人々は鍾会を、漢の名軍師になぞらえて「今の張良だ」とうわさした。", "quote": "わが知恵があれば、勝てぬいくさなどない。", "cond": [{"t": "year_ge", "y": 250}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・鍾会伝"},
  {"name": "諸葛誕", "title": "諸葛公のために", "text": "諸葛誕は、ふだんから部下をわけへだてなく大切にした。そのため部下たちは「諸葛公のためなら死んでもくやまない」と言い、心から諸葛誕にしたがった。", "quote": "そなたたちこそ、わしのいちばんの宝だ。", "cond": [], "fx": [{"t": "gens_loyalty", "v": 5}, {"t": "city", "k": "train", "v": 5}], "src": "正史・諸葛誕伝"},
  {"name": "毌丘倹", "title": "丸都をうつ", "text": "毌丘倹は高句麗をせめ、その都の丸都を打ち破った。勝ったしるしに、山に石をきざんで、てがらを書き残した。", "quote": "このいさおし、石にきざんで後の世に伝えよ。", "cond": [{"t": "year_ge", "y": 240}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "all", "k": "train", "v": 4}], "src": "正史・毌丘倹伝"},
  {"name": "陳泰", "title": "狄道を救う", "text": "姜維に囲まれた狄道の城を救うため、陳泰は山ごしに兵を進め、高いところに陣を取った。思わぬ援軍におどろいた姜維は、囲みをといて引き上げた。", "quote": "急ぐが、あわてるな。高きを取れば敵は退く。", "cond": [{"t": "foe", "who": "姜維"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "foe_city", "k": "train", "v": -5}], "src": "正史・陳泰伝"},
  {"name": "文欽", "title": "親子の夜討ち", "text": "文欽は息子の文鴦と力を合わせ、夜のうちに敵の陣へなぐりこんだ。父と子の大声がひびきわたり、敵兵はあわてふためいた。", "quote": "鴦よ、続け！父子で敵陣をかき回してやれ！", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -6}], "src": "正史・毌丘倹伝 裴注 / 演義第110回"},
  {"name": "張嶷", "title": "越巂の別れ", "text": "張嶷は越巂の地を長くおさめ、山の民ともなかよくした。張嶷がよそへうつる日、民たちは車にすがって泣き、別れをおしんだ。", "quote": "泣くな。そなたらのことは、けして忘れぬ。", "cond": [], "fx": [{"t": "city", "k": "loyal", "v": 8}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・張嶷伝"},
  {"name": "鄧芝", "title": "呉への使者", "text": "鄧芝は使者として呉へ行き、孫権とまっすぐに話し合った。うそのないことばに孫権は笑い、蜀と呉はふたたび手を結んだ。", "quote": "まことの心でお話ししております。それだけです。", "cond": [{"t": "year_ge", "y": 222}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・鄧芝伝 / 演義第86回"},
  {"name": "宗預", "title": "孫権との問答", "text": "宗預は呉へ使いに行き、孫権に国ざかいの守りのことを問いつめられた。宗預はおそれず、すじの通った答えを返し、孫権にすっかり気に入られた。", "quote": "そちらが守りをふやせば、こちらもふやす。当然のことです。", "cond": [{"t": "year_ge", "y": 230}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "loyalty", "v": 10}], "src": "正史・宗預伝"},
  {"name": "張翼", "title": "役目をつらぬく", "text": "南の地で反乱が起き、張翼は役目をとかれることになった。それでも張翼は、あとの人が来るまで兵や食料を集め、守りの用意をつづけた。", "quote": "戦の場をはなれるまでは、わしの務めだ。", "cond": [], "fx": [{"t": "city", "k": "food", "v": 3000}, {"t": "loyalty", "v": 10}], "src": "正史・張翼伝"},
  {"name": "霍峻", "title": "葭萌を守る", "text": "霍峻はわずかな兵で葭萌の城を守った。張魯の使いが「いっしょに守ろう」とさそっても「わしの首は取れても、城はわたさぬ」とことわり、大軍にもたえぬいた。", "quote": "わしの首は取れても、この城は取らせぬ！", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "city", "k": "def", "v": 150}, {"t": "loyalty", "v": 10}], "src": "正史・霍峻伝"},
  {"name": "楊儀", "title": "口わざわい", "text": "楊儀は、自分の手がらにくらべて役目が軽いと不満をつのらせた。ついに「あのとき魏についていれば」とぐちをこぼし、それが知れわたって立場を悪くした。", "quote": "わしがいなければ、軍は帰れなかったのだぞ！", "cond": [{"t": "year_ge", "y": 234}], "fx": [{"t": "loyalty", "v": -20}, {"t": "stat", "k": "cha", "v": -1}], "src": "正史・楊儀伝"},
  {"name": "許靖", "title": "名士をうやまう", "text": "許靖はかつて城から逃げようとしたため、劉備に好かれていなかった。けれど法正が「名高い許靖を大切にすれば、天下の人が殿を見直します」と進め、劉備は許靖を手あつくもてなした。", "quote": "この老いた身でも、国の飾りくらいにはなりましょう", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "loyalty", "v": 12}, {"t": "gens_loyalty", "v": 4}], "src": "正史・法正伝/許靖伝"},
  {"name": "孫翊", "title": "兄に似た勇気", "text": "孫翊は気性がはげしく、勇ましいところが兄の孫策によく似ていた。兵たちは孫翊が先頭に立つ姿に孫策の面影を見て、大いに元気づいた。", "quote": "兄上のように、おれが一番前で戦ってやる！", "cond": [{"t": "with", "who": "孫権"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "正史・孫翊伝（驍悍果烈で孫策に似る）"},
  {"name": "孫桓", "title": "助けがなくとも", "text": "孫桓は夷道の城で劉備の大軍にかこまれたが、陸遜は助けを送らなかった。孫桓は守りぬき、勝ったあと、陸遜の作戦が正しかったと知って心から感心した。", "quote": "助けが来ぬと恨みましたが、今やっと分かりました", "cond": [{"t": "with", "who": "陸遜"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "def", "v": 100}, {"t": "loyalty", "v": 8}], "src": "正史・陸遜伝/孫桓伝"},
  {"name": "孫韶", "title": "夜の京城", "text": "孫権が夜に京城の近くへ来て、ためしに攻めるふりをした。すると兵たちはすぐ城壁にかけ上がり、守りをかためた。孫権はその見事さに大喜びした。", "quote": "いつ攻められても、この城は落ちませぬ", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "city", "k": "train", "v": 5}, {"t": "loyalty", "v": 8}], "src": "正史・孫韶伝"},
  {"name": "陳武", "title": "殿の訪問", "text": "陳武は心が広く、まわりの人を大切にしたので、多くの人に慕われた。孫権は陳武をとても好み、何度も陳武の家をたずねた。", "quote": "殿のためなら、この命いつでもさし出しまする", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "gens_loyalty", "v": 4}], "src": "正史・陳武伝"},
  {"name": "董襲", "title": "綱を断ち切る", "text": "黄祖の軍は大きな船を綱でつなぎ、川をふさいでいた。董襲は凌統と決死の兵をひきい、よろいを二重に着て敵の船に近づくと、刀で綱を切って道を開いた。", "quote": "この綱さえ切れば、道は開ける！", "cond": [{"t": "foe", "who": "黄祖"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -6}], "src": "正史・董襲伝"},
  {"name": "賀斉", "title": "がけを登る兵", "text": "山の民は高いがけの上にたてこもり、近づけなかった。賀斉は身軽な兵を選び、鉄のほこをがけに打ちこんで登らせた。夜のうちに頂上に着いた兵が太鼓を鳴らすと、敵はおどろいてくずれた。", "quote": "道がなければ、作ればよいのだ", "cond": [], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・賀斉伝（林歴山の戦い）"},
  {"name": "全琮", "title": "米を配る", "text": "全琮は父に言われ、米を売りに呉へ行った。ところが町で困っている人々を見て、米をみな配ってしまい、からの船で帰った。父は怒ったが、わけを聞いて感心した。", "quote": "商いより、今こまっている人を救うほうが先です", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・全琮伝"},
  {"name": "歩騭", "title": "瓜を作る日々", "text": "若いころの歩騭はまずしく、友とともに瓜を作って暮らした。土地の有力者に冷たくあしらわれても、歩騭はまったく気にせず、学問をつづけた。", "quote": "見下されて怒るほど、わたしは小さくはありませぬ", "cond": [], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "pct", "k": "farm", "v": 4}], "src": "正史・歩騭伝"},
  {"name": "諸葛恪", "title": "ロバの顔", "text": "孫権は、顔の長い諸葛瑾をからかい、ロバの顔に「諸葛子瑜」と書いた札をつけた。息子の諸葛恪は筆を借りて「之驢」と二字を書き足し、一同は大笑い。孫権はそのロバを諸葛恪にあたえた。", "quote": "二字足せば、父のロバでございましょう", "cond": [{"t": "lord", "who": "孫権"}, {"t": "with", "who": "諸葛瑾"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・諸葛恪伝（裴注・恪別伝）"},
  {"name": "陸抗", "title": "敵将の薬", "text": "陸抗が病気になると、国境で向かい合う羊祜が薬を送ってきた。家臣は毒をうたがったが、陸抗は迷わず飲んだ。二人は敵どうしでも、たがいを信じ合っていた。", "quote": "羊叔子が、人に毒を盛るような男であろうか", "cond": [{"t": "year_ge", "y": 250}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・陸抗伝（裴注・漢晋春秋）"},
  {"name": "朱治", "title": "若君を推す", "text": "朱治は、まだ若い孫権の才能を早くから見ぬき、役人に推薦した。孫権はこの恩を忘れず、のちに君主となってからも朱治を深くうやまった。", "quote": "この若君こそ、江東をになうお方", "cond": [{"t": "with", "who": "孫権"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "gens_loyalty", "v": 4}], "src": "正史・朱治伝"},
  {"name": "呂岱", "title": "耳に痛い友", "text": "呂岱の友の徐原は、呂岱にあやまちがあると、えんりょなく注意した。人々は呂岱が怒ると思ったが、呂岱はかえって徐原を大切にし、自分を正してくれる友だとほめた。", "quote": "きびしく言ってくれる友こそ、わしの宝よ", "cond": [], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・呂岱伝"},
  {"name": "張楊", "title": "楊安殿", "text": "長安からのがれた献帝が洛陽にもどると、宮殿は焼けあとだった。張楊は宮殿を建て直し、その恩をたたえて、宮殿は張楊の名から「楊安殿」と名づけられた。", "quote": "天子をお守りするのは、臣下のつとめにございます", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "city", "k": "def", "v": 80}], "src": "正史・張楊伝（後漢書・董卓伝）"},
  {"name": "臧洪", "title": "誓いの壇", "text": "董卓をたおすため諸侯が集まった時、だれも誓いの言葉を読む役を引き受けなかった。臧洪が壇に登り、熱い言葉で誓いを読み上げると、その場の者はみな涙を流して心を一つにした。", "quote": "漢の世を救うため、心を一つにして戦おう！", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "gens_loyalty", "v": 6}], "src": "正史・臧洪伝"},
  {"name": "鮑信", "title": "英雄を見ぬく", "text": "鮑信は、まだ力の小さい曹操を見て「乱れた世をまとめられるのは、この人だ」と見ぬいた。鮑信は曹操と深く心を通わせ、力をあわせた。", "quote": "世をしずめる英雄は、あなたをおいてほかにない", "cond": [{"t": "with", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 12}, {"t": "stat", "k": "cha", "v": 1, "who": "曹操"}], "src": "正史・武帝紀（裴注・魏書）/鮑勛伝"},
  {"name": "張邈", "title": "古い友情", "text": "袁紹が曹操に「張邈を殺せ」と言ったが、曹操は「孟卓は友だ」とことわった。曹操は家族に「わしが戦で死んだら、孟卓をたよれ」と言うほど、張邈を信じていた。", "quote": "孟徳との友情は、だれにも裂けぬ", "cond": [{"t": "with", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 12}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・張邈伝"},
  {"name": "司馬徽", "title": "伏龍と鳳雛", "text": "司馬徽は、だれのことも「好し、好し」とほめる、おだやかな人だった。そんな司馬徽が「伏龍・鳳雛のどちらかを得れば天下が取れる」と語り、すぐれた人を教えてくれた。", "quote": "好し、好し。世の中には、まだ眠れる龍がおりますぞ", "cond": [], "fx": [{"t": "recruit", "n": 2}], "src": "正史・諸葛亮伝（裴注・襄陽記）/演義第35回"},
  {"name": "許劭", "title": "月旦評", "text": "許劭は毎月はじめに人物の評判を語る「月旦評」を開き、その言葉は天下に知られた。許劭にほめられたいと、各地から才ある者がたずねてきた。", "quote": "人を見るのは、顔ではなく心ですぞ", "cond": [], "fx": [{"t": "recruit", "n": 1}, {"t": "stat", "k": "cha", "v": 1}], "src": "後漢書・許劭伝/正史・武帝紀（裴注）"},
  {"name": "朱霊", "title": "真の明主", "text": "朱霊はもともと袁紹の将で、曹操を助けに来ていた。戦いが終わっても袁紹のもとへ帰らず、「多くの人を見てきたが、曹公ほどの人はいない」と曹操に仕えることを決めた。", "quote": "この方こそ、まことの明主だ", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・徐晃伝（裴注・九州春秋）"},
  {"name": "辛評", "title": "疑われた忠臣", "text": "弟の辛毗が敵の陣営に仕えていたため、辛評は君主から「敵と通じているのでは」と疑われた。まごころをうたがわれた辛評は深く傷つき、すっかり元気をなくしてしまった。", "quote": "弟は弟、わたしはわたし。なぜ信じてくださらぬ", "cond": [{"t": "foe", "who": "辛毗"}], "fx": [{"t": "loyalty", "v": -12}, {"t": "stat", "k": "pol", "v": -1}], "src": "演義（袁譚が辛評を疑う場面）"},
  {"name": "呂虔", "title": "泰山の精兵", "text": "呂虔は荒れた土地をおさめ、山にこもる賊たちを説きふせて従わせた。その中から強い者を選んで兵にしたので、呂虔の土地には強い兵がそろった。", "quote": "賊も、良い主に会えば良い兵になる", "cond": [], "fx": [{"t": "city", "k": "troops", "v": 2500}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・呂虔伝"},
  {"name": "呉班", "title": "司馬懿を退ける", "text": "魏の司馬懿が蜀の陣を攻めてきた。呉班は魏延・高翔とともに迎え討つよう命じられ、魏の軍を大いに打ち破った。", "quote": "司馬懿といえど、おそれるに足らず！", "cond": [{"t": "foe", "who": "司馬懿"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "foe_city", "k": "train", "v": -6}], "src": "正史・諸葛亮伝（裴注・漢晋春秋）"},
  {"name": "陳到", "title": "白毦兵", "text": "陳到は劉備の親衛隊「白毦兵」をひきいた。その名と地位はいつも趙雲に次ぎ、忠義と勇気で知られた。陳到のきたえた兵は、主君の守りのかなめとなった。", "quote": "殿の身は、この陳到が必ずお守りする", "cond": [{"t": "lord", "who": "劉備"}], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "loyalty", "v": 8}], "src": "正史・楊戯伝（季漢輔臣賛）/陳到"},
  {"name": "黄承彦", "title": "才ある娘", "text": "黄承彦は諸葛亮に「わたしには髪が黄色く色の黒い娘がいるが、才知はあなたにふさわしい」と話した。諸葛亮はよろこんで娘を妻にむかえた。", "quote": "見た目はさておき、才は天下一品の娘ですぞ", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "loyalty", "v": 10, "who": "諸葛亮"}, {"t": "stat", "k": "int", "v": 1, "who": "諸葛亮"}], "src": "正史・諸葛亮伝（裴注・襄陽記）"},
  {"name": "王双", "title": "流星鎚", "text": "王双は大きな刀をふるい、流星鎚をかくし持つ豪傑だった。曹真の先陣に立つと、王双の暴れぶりに敵の兵はおそれおののいた。", "quote": "おれの鎚から逃げられる者はおらぬわ！", "cond": [{"t": "with", "who": "曹真"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -5}], "src": "演義第97回"},
  {"name": "楊奉", "title": "天子を守る", "text": "長安をのがれた献帝が東へ向かうと、追手がせまってきた。楊奉は兵をひきいて献帝のそばにつき、追手と戦って天子を守った。", "quote": "天子は、この楊奉がお守りいたす！", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "loyalty", "v": 8}], "src": "正史・董卓伝/後漢書・董卓伝"},
  {"name": "韓暹", "title": "おごる心", "text": "韓暹は天子を守った手がらで高い位をもらったが、それを鼻にかけ、えらそうにふるまうようになった。まわりの者は韓暹から心がはなれていった。", "quote": "天子を守ったのはこのおれだ。だれにも文句は言わせん", "cond": [], "fx": [{"t": "loyalty", "v": -10}, {"t": "city", "k": "loyal", "v": -5}], "src": "正史・董卓伝/後漢書・董卓伝"},
  {"name": "管亥", "title": "北海をかこむ", "text": "黄巾の将・管亥は大軍をひきいて北海の孔融の城をかこみ、外との行き来を断ち切った。城の中の者たちは、管亥の勢いにふるえあがった。", "quote": "食い物をよこせ！さもなくば城ごと踏みつぶす！", "cond": [{"t": "foe", "who": "孔融"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "loyal", "v": -6}], "src": "正史・太史慈伝/演義第11回"},
  {"name": "胡車児", "title": "双戟をぬすむ", "text": "力じまんの胡車児は、典韋が酒によっているすきに、典韋の大事な双戟をこっそりぬすみ出した。武器をなくした典韋は、もう力を出しきれなかった。", "quote": "どんな豪傑も、武器がなければただの人よ", "cond": [{"t": "with", "who": "張繍"}, {"t": "foe", "who": "典韋"}], "fx": [{"t": "foe_city", "k": "train", "v": -8}, {"t": "stat", "k": "int", "v": 1}], "src": "演義第16回"},
  {"name": "曹叡", "title": "子鹿を射ず", "text": "狩りの日、父の曹丕が母鹿を射て、曹叡に子鹿も射よと命じた。曹叡は涙を流して弓を下ろした。そのやさしさに曹丕は心を動かされた。", "quote": "母はもう討たれました。子まで射ることはできません", "cond": [{"t": "with", "who": "曹丕"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "loyalty", "v": 10}], "src": "正史・明帝紀注引『魏末伝』"},
  {"name": "曹沖", "title": "象の重さ", "text": "孫権から大きな象が贈られたが、重さを量れる者がいなかった。曹沖は象を船に乗せて水の線に印をつけ、同じ所まで石を積んで量ればよいと言った。", "quote": "象の代わりに、石を量ればよいのです", "cond": [{"t": "with", "who": "曹操"}], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "gens_loyalty", "v": 3}], "src": "正史・鄧哀王沖伝"},
  {"name": "曹彪", "title": "兄から贈られた詩", "text": "兄の曹植と一緒に帰る旅は、とちゅうで止められてしまった。曹植は弟を思う詩を贈り、曹彪はその言葉を胸に、自分の土地を大切に治めようと決めた。", "quote": "兄上の詩は、わたしの宝です", "cond": [{"t": "with", "who": "曹植"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・陳思王植伝注引『魏氏春秋』（贈白馬王彪）"},
  {"name": "夏侯楙", "title": "蔵をうるおす", "text": "夏侯楙は戦は苦手だったが、お金のやりくりは得意だった。その才を生かして、守る町の蔵をこつこつと増やしていった。", "quote": "戦は人にまかせよう。わしは蔵をいっぱいにするぞ", "cond": [], "fx": [{"t": "city", "k": "gold", "v": 600}, {"t": "city", "k": "food", "v": 3000}], "src": "正史・夏侯惇伝注引『魏略』（武略なく財を好む）"},
  {"name": "夏侯称", "title": "若き勇者の稽古", "text": "父の夏侯淵ゆずりの勇ましさを持つ夏侯称は、若者たちを集めて馬と弓の稽古にはげんだ。その元気に、兵たちも負けじと腕をみがいた。", "quote": "父上のように、だれより速く駆けてみせる", "cond": [{"t": "with", "who": "夏侯淵"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作"},
  {"name": "夏侯恵", "title": "鍾毓との議論", "text": "夏侯恵は若いころから弁が立つことで知られた。鍾毓と何度も議論をたたかわせ、そのたびに二人とも考えを深めていった。", "quote": "言い負かすためではない。正しい答えを探すためだ", "cond": [{"t": "with", "who": "鍾毓"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "int", "v": 1, "who": "鍾毓"}], "src": "正史・夏侯淵伝注（鍾毓と論じ合う）"},
  {"name": "夏侯和", "title": "都をまじめに治める", "text": "夏侯和は都の役人として、町の人の声によく耳をかたむけた。もめごとをていねいに収め、町は少しずつ落ち着いていった。", "quote": "小さな声こそ、よく聞かねばならぬ", "cond": [{"t": "owns", "city": "洛陽"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 5}], "src": "経歴（河南尹・太常）にもとづく創作"},
  {"name": "夏侯玄", "title": "人を選ぶしくみ", "text": "夏侯玄は、役人を選ぶしくみに無理が多いと考え、司馬懿に手紙で改め方を説いた。その考えは多くの人の心を動かした。", "quote": "人を選ぶ道が正しくなければ、国は強くなりません", "cond": [{"t": "with", "who": "司馬懿"}], "fx": [{"t": "stat", "k": "pol", "v": 2}, {"t": "gens_loyalty", "v": 4}], "src": "正史・夏侯玄伝（時事の議）"},
  {"name": "曹羲", "title": "兄をいさめる", "text": "兄の曹爽がおごり高ぶるのを見て、曹羲は心配でならなかった。思いきって兄をいさめると、曹爽も少しだけ耳をかたむけた。", "quote": "兄上、油断こそがいちばんの敵です", "cond": [{"t": "with", "who": "曹爽"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "gens_loyalty", "v": 3}], "src": "正史・曹爽伝（弟曹羲が兄を戒める）"},
  {"name": "曹肇", "title": "天子の信頼", "text": "曹肇は明帝曹叡にあつく信頼され、そば近くで大切な相談を受けるようになった。曹肇はその期待にこたえようと心に決めた。", "quote": "陛下のご信頼、決してむだにはいたしません", "cond": [{"t": "with", "who": "曹叡"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・曹休伝/曹爽伝（明帝が後見役に望む）"},
  {"name": "典満", "title": "父の名を継ぐ", "text": "曹操は亡き典韋を思い出すたび、その子の典満をそばに呼んで取り立てた。典満は父に負けぬ働きをしようと誓った。", "quote": "父のように、命をかけて殿をお守りします", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "war", "v": 1}], "src": "正史・典韋伝"},
  {"name": "許儀", "title": "道づくりのしくじり", "text": "許儀は軍の通る道をつくる役目をまかされたが、仕上がりが悪かった。鍾会は父許褚の手柄にも目をくれず、きびしく責めた。", "quote": "父上の名に、泥をぬってしまった……", "cond": [{"t": "with", "who": "鍾会"}], "fx": [{"t": "loyalty", "v": -15}], "src": "正史・許褚伝"},
  {"name": "張虎", "title": "騎馬の稽古", "text": "父張遼の勇ましい話を聞いて育った張虎は、騎馬隊を率いる稽古にはげんだ。その姿に、若い兵たちも元気づけられた。", "quote": "父上の名に恥じぬ騎馬隊をつくるぞ", "cond": [{"t": "with", "who": "張遼"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作"},
  {"name": "楽綝", "title": "先頭に立つ", "text": "体は小さくても、いつも先頭で戦った父楽進のように、楽綝も兵の前に立って守りをかためた。兵たちはその背中を信じてついていった。", "quote": "父上のように、まず自分が前に出る", "cond": [], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作（父楽進の気風）"},
  {"name": "徐蓋", "title": "父の教え", "text": "徐蓋は、父徐晃の落ち着いた戦い方を間近で学んだ。あわてず、よく見てから動くことを心がけ、兵の動きもそろってきた。", "quote": "急ぐな。よく見てから動けと、父に教わった", "cond": [{"t": "with", "who": "徐晃"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作"},
  {"name": "龐会", "title": "父の勇を継ぐ", "text": "龐会は、父龐徳が最後まで降らずに戦い抜いた話を胸に、だれにも負けぬ武芸をみがいた。その気迫に、まわりの兵も奮い立った。", "quote": "父上の無念、この腕で晴らしてみせる", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "loyalty", "v": 10}], "src": "正史・龐徳伝（子の龐会は父の勇を継ぐ）"},
  {"name": "鍾毓", "title": "公平な裁き", "text": "裁きの役についた鍾毓は、身分の高い低いにかかわらず、話をよく聞いて正しく裁いた。町の人々は安心して暮らせるようになった。", "quote": "法は、だれにも同じでなければならぬ", "cond": [], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 6}], "src": "経歴（廷尉）にもとづく創作"},
  {"name": "荀惲", "title": "公主をむかえる", "text": "荀惲は曹操の娘、安陽公主を妻にむかえた。曹家と荀家の結びつきは強くなり、荀惲も主君のために力をつくそうと誓った。", "quote": "この縁、決して軽くは思いません", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・荀彧伝"},
  {"name": "荀顗", "title": "親思いの若者", "text": "荀顗は幼いころから親思いで知られ、学問にもくわしかった。司馬懿はその才を見こみ、めずらしい人物だとほめたたえた。", "quote": "親を大切にできずして、国に尽くせましょうか", "cond": [{"t": "with", "who": "司馬懿"}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "stat", "k": "pol", "v": 1}], "src": "『晋書』荀顗伝"},
  {"name": "郭奕", "title": "父ゆずりの学問", "text": "郭奕は父郭嘉と同じく、本を読むのが大好きだった。学んだことを人に分かりやすく話し、仲間たちも学問に親しむようになった。", "quote": "父の残した知恵を、わたしが伝えていきます", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "gens_loyalty", "v": 3}], "src": "経歴にもとづく創作"},
  {"name": "王粛", "title": "敵の家族を大切に", "text": "反乱が起きたとき、王粛は司馬師に、敵の兵の家族を手厚くあつかうよう説いた。家族の無事を知った敵兵たちは、戦う気持ちをなくしていった。", "quote": "家族を守れば、敵の心はおのずと離れます", "cond": [{"t": "with", "who": "司馬師"}], "fx": [{"t": "foe_city", "k": "loyal", "v": -5}, {"t": "all", "k": "loyal", "v": 3}], "src": "正史・王粛伝（毌丘倹の乱での献策）"},
  {"name": "鄧忠", "title": "綿竹の再突撃", "text": "綿竹で敵の守りはかたく、鄧忠はいったん引き返した。父鄧艾にきびしくしかられると、もう一度突っこんで、ついに敵陣を破った。", "quote": "父上、今度こそ破ってみせます", "cond": [{"t": "with", "who": "鄧艾"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 6}], "src": "正史・鄧艾伝"},
  {"name": "文鴦", "title": "単騎で追手を退ける", "text": "父文欽とともに敵陣へ攻めこんだ文鴦は、退くとき、ただ一騎で追ってくる大軍に向かっていった。その強さに、追手は近づけなくなった。", "quote": "来るなら来い！まとめて相手をしてやる", "cond": [{"t": "with", "who": "文欽"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "foe_city", "k": "train", "v": -6}], "src": "演義第110回（文鴦単騎退雄兵）"},
  {"name": "文虎", "title": "許された兄弟", "text": "父を失い、兄の文鴦と城を抜け出した文虎は、司馬昭のもとへ降った。司馬昭は罪を問わずに受け入れ、文虎はその恩に報いようと誓った。", "quote": "この命、救ってくださった方のために使います", "cond": [{"t": "with", "who": "司馬昭"}], "fx": [{"t": "loyalty", "v": 20}], "src": "正史・諸葛誕伝/文欽伝注"},
  {"name": "諸葛靚", "title": "曲げぬ心", "text": "諸葛靚は父を討った司馬氏をけっして許さず、その都の方角に向かって座ることさえしなかった。そして今の主君に、まっすぐ仕え続けた。", "quote": "父の無念を忘れて、生きることはできませぬ", "cond": [{"t": "foe", "who": "司馬昭"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "lead", "v": 1}], "src": "『晋書』諸葛靚の記述・正史・諸葛誕伝"},
  {"name": "張緝", "title": "先を見ぬく目", "text": "呉の諸葛恪が勝ちを重ねていたころ、張緝は「あの者はやがて身をほろぼす」と見ぬいた。そのとおりになり、司馬師は張緝の知恵に感心した。", "quote": "勝ちにおごる者は、長くは続きません", "cond": [{"t": "with", "who": "司馬師"}], "fx": [{"t": "stat", "k": "int", "v": 2}], "src": "正史・張既伝注引『魏略』"},
  {"name": "賈充", "title": "新しい決まり", "text": "賈充は多くの学者を集め、ばらばらだった国の決まりを、分かりやすく一つにまとめた。人々は何をしてはいけないかが分かり、国は落ち着いた。", "quote": "決まりが分かりやすければ、民は迷わぬ", "cond": [{"t": "with", "who": "司馬昭"}], "fx": [{"t": "stat", "k": "pol", "v": 2}, {"t": "all", "k": "loyal", "v": 4}], "src": "『晋書』刑法志（泰始律令の編纂）"},
  {"name": "辛憲英", "title": "喜ぶより慎め", "text": "若君が跡継ぎに決まり、父・辛毗は大喜びで帰ってきた。辛憲英は「国を背負う重い務めです。喜ぶより気を引きしめるべきです」と父に静かに語った。", "quote": "重い務めを受けた時こそ、浮かれず慎むものです", "cond": [{"t": "with", "who": "辛毗"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "pol", "v": 1, "who": "辛毗"}], "src": "正史・辛毗伝の裴注（曹丕立太子の時の逸話）"},
  {"name": "袁耀", "title": "名門の跡取り", "text": "名門袁家の跡取りとして、袁耀は父・袁術の兵たちの間を回り、声をかけて歩いた。家の名を守ろうとする姿に、兵たちも少し落ち着きを取り戻した。", "quote": "袁家の名に、これ以上どろをぬるわけにはいかぬ", "cond": [{"t": "with", "who": "袁術"}], "fx": [{"t": "city", "k": "loyal", "v": 5}, {"t": "loyalty", "v": 5}], "src": "経歴にもとづく創作"},
  {"name": "劉循", "title": "雒城の守り", "text": "劉循は仲間の将たちとともに城を固く守り、攻め寄せる敵を一年あまりも寄せつけなかった。父の国を守る強い心が、兵たちを支えた。", "quote": "父上の国、この城でかならず守ってみせる", "cond": [{"t": "with", "who": "劉璋"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "city", "k": "train", "v": 5}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・先主伝の裴注（雒城の籠城）"},
  {"name": "劉闡", "title": "父を支える子", "text": "劉闡は父・劉璋のそばにいつも付きそい、新しい土地の人々の声によく耳をかたむけた。おだやかな人柄に、町の人々も心を開いた。", "quote": "父上、まずは民の話を聞いてまいります", "cond": [{"t": "with", "who": "劉璋"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "city", "k": "loyal", "v": 5}], "src": "経歴にもとづく創作（父とともに荊州へ移り、のち呉に仕えた）"},
  {"name": "馬休", "title": "兄に負けじと", "text": "父・馬騰のもとで、馬休は兄・馬超に負けじと毎日馬を走らせた。その熱心さに、若い騎兵たちもいっしょに腕をみがいた。", "quote": "兄上ばかりに手がらはやらぬぞ！", "cond": [{"t": "with", "who": "馬騰"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "経歴にもとづく創作"},
  {"name": "馬鉄", "title": "西涼の馬", "text": "馬鉄は父・馬騰に命じられ、西涼の良い馬を集めて新しい騎兵隊をつくった。風のように駆ける隊に、父も満足そうにうなずいた。", "quote": "この馬たちとなら、どこまでも駆けてゆけます", "cond": [{"t": "with", "who": "馬騰"}], "fx": [{"t": "city", "k": "troops", "v": 1500}, {"t": "city", "k": "train", "v": 4}], "src": "経歴にもとづく創作"},
  {"name": "陶商", "title": "一歩引く心", "text": "父・陶謙の跡を自分が継ぐより、徳のある人に任せるほうが民のためになる。陶商はそう考えて表に立たず、陰から町の暮らしを支えた。", "quote": "わたしの名より、民の安らぎのほうが大事です", "cond": [{"t": "with", "who": "陶謙"}], "fx": [{"t": "city", "k": "loyal", "v": 6}, {"t": "stat", "k": "cha", "v": 1}], "src": "経歴にもとづく創作（正史・陶謙伝：二子は仕官せず）"},
  {"name": "公孫恭", "title": "遼東の留守役", "text": "兄・公孫康の子どもたちはまだ幼い。公孫恭は「この子たちが育つまで」と遼東の守りを引き受け、城壁の手入れを急がせた。", "quote": "甥たちが大きくなるまで、わしがこの地を守ろう", "cond": [{"t": "owns", "city": "襄平"}], "fx": [{"t": "city", "k": "def", "v": 80}, {"t": "loyalty", "v": 5}], "src": "正史・公孫度伝（兄の子が幼く跡を継ぐ）"},
  {"name": "公孫晃", "title": "都の人質", "text": "人質として都で暮らす公孫晃は、遠い遼東で力をのばす弟・公孫淵のことを案じていた。公孫晃は、遼東のようすを主君にくわしく伝えた。", "quote": "弟は危ういことを考えております。どうかご用心を", "cond": [{"t": "foe", "who": "公孫淵"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・公孫度伝（公孫晃は人質として洛陽へ）"},
  {"name": "劉範", "title": "都をすくう計画", "text": "都で役についていた劉範は、馬騰らと力を合わせ、都をおさえる李傕をたおす計画をひそかに進めた。", "quote": "天子さまを、悪い者の手からお救いせねば", "cond": [{"t": "with", "who": "馬騰"}, {"t": "foe", "who": "李傕"}], "fx": [{"t": "foe_city", "k": "loyal", "v": -5}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・劉焉伝（馬騰・韓遂と結び李傕を討とうとした）"},
  {"name": "劉和", "title": "父のかたき", "text": "父・劉虞をうばった公孫瓚に、劉和は父の昔の家来たちと手を組んで立ち向かうことを決めた。", "quote": "父上のうらみ、かならず晴らしてみせる", "cond": [{"t": "foe", "who": "公孫瓚"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "loyal", "v": -5}], "src": "正史・公孫瓚伝（劉和が父の旧臣と公孫瓚を攻める）"},
  {"name": "皇甫堅寿", "title": "父の命ごい", "text": "董卓が父・皇甫嵩を罰しようとした時、堅寿は宴の席にかけつけ、父のために心からうったえた。その言葉に心を動かされ、董卓も父を許した。", "quote": "どうか、父の命だけはお助けください", "cond": [{"t": "with", "who": "皇甫嵩"}, {"t": "with", "who": "董卓"}], "fx": [{"t": "loyalty", "v": 15, "who": "皇甫嵩"}, {"t": "stat", "k": "cha", "v": 1}], "src": "後漢書・皇甫嵩伝"},
  {"name": "盧毓", "title": "画にかいた餅", "text": "「名声だけの人は、地面にかいた餅のようで食べられぬ」と主君に言われた盧毓は、名声より実際の働きを確かめて人を選ぶよう進めた。", "quote": "名声よりも、その人の働きを見て選びましょう", "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "recruit", "n": 1}], "src": "正史・盧毓伝（画餅の故事）"},
  {"name": "関索", "title": "南征への参陣", "text": "荊州で傷を負い、鮑家で養生していた関索が、ついに諸葛亮の陣にかけつけた。諸葛亮は喜び、関索を先鋒に任じた。", "quote": "父の名に恥じぬ働きを、この南の地でお見せします", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "loyalty", "v": 10}, {"t": "city", "k": "train", "v": 5}], "src": "演義第87回"},
  {"name": "関統", "title": "関家の名にかけて", "text": "祖父・関羽の名に恥じぬよう、関統は朝早くから兵の訓練にはげんだ。まじめな姿に、兵たちも心から従った。", "quote": "関の名を背負う者として、なまけてはおれぬ", "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "stat", "k": "cha", "v": 1}], "src": "経歴にもとづく創作"},
  {"name": "関彝", "title": "受けつぐ武勇", "text": "関家の武勇を受けつぐ関彝は、町の守りを自ら見回り、くずれかけた所をすぐに直させた。", "quote": "祖父のように、この地の盾となろう", "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "def", "v": 60}], "src": "経歴にもとづく創作"},
  {"name": "張紹", "title": "そば近く仕える", "text": "張飛の子・張紹は、主君のそば近くで国の仕事を支えた。父とはちがう落ち着いた働きぶりに、主君も信頼をよせた。", "quote": "父は槍で、わたしは筆で、お仕えいたします", "cond": [{"t": "with", "who": "劉禅"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "all", "k": "gold", "v": 150}], "src": "経歴にもとづく創作（尚書僕射として蜀に仕えた）"},
  {"name": "張遵", "title": "祖父ゆずりの勇気", "text": "張飛の孫・張遵は、諸葛瞻とともに、攻め寄せる鄧艾の軍の前に立ちはだかった。祖父ゆずりの勇気に、兵たちもふるい立った。", "quote": "張飛の孫が、ここで引き下がるものか！", "cond": [{"t": "with", "who": "諸葛瞻"}, {"t": "foe", "who": "鄧艾"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 8}], "src": "正史・張飛伝/諸葛瞻伝（綿竹の戦い）"},
  {"name": "趙統", "title": "父の教え", "text": "趙統は父・趙雲から受けついだ「こつこつ働く心」を大切にし、兵や民に分けへだてなく接した。", "quote": "父のように、まっすぐにお仕えするだけです", "fx": [{"t": "city", "k": "loyal", "v": 5}, {"t": "city", "k": "train", "v": 4}], "src": "経歴にもとづく創作"},
  {"name": "趙広", "title": "沓中の先頭", "text": "趙広は姜維にしたがって遠い沓中の地まで出陣し、いつも先頭に立って戦った。父・趙雲を思わせる姿だった。", "quote": "父上の子として、恥ずかしい戦はできませぬ", "cond": [{"t": "with", "who": "姜維"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "loyalty", "v": 8}, {"t": "city", "k": "train", "v": 6}], "src": "正史・趙雲伝（姜維に従い沓中で戦った）"},
  {"name": "諸葛瞻", "title": "王の誘いをけって", "text": "鄧艾から「降れば王にしてやろう」という手紙が届いた。諸葛瞻はきっぱりと断り、国を守るために戦う道を選んだ。", "quote": "父の名にかけて、敵に頭を下げることはできぬ", "cond": [{"t": "foe", "who": "鄧艾"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "gens_loyalty", "v": 5}], "src": "正史・諸葛瞻伝（鄧艾の降伏勧告を拒む）"},
  {"name": "諸葛喬", "title": "特別あつかい無用", "text": "漢中で、諸葛喬は父・諸葛亮の言いつけで、ほかの将の子どもたちと同じく少ない兵をひきいて谷の守りについた。えらぶらない姿に、皆が感心した。", "quote": "丞相の子だからと、甘えるわけにはまいりません", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "city", "k": "def", "v": 60}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・諸葛亮伝の裴注（諸葛亮の書簡）"},
  {"name": "黄崇", "title": "涙のうったえ", "text": "黄崇は「今すぐ山の守りやすい所を押さえるべきです」と、諸葛瞻に何度もうったえた。涙ながらの言葉に、ついに諸葛瞻も兵を動かした。", "quote": "ぐずぐずしていては、敵に先をこされます！", "cond": [{"t": "with", "who": "諸葛瞻"}, {"t": "foe", "who": "鄧艾"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・黄権伝（黄崇が諸葛瞻に要地確保を説く）"},
  {"name": "馬承", "title": "騎馬の血", "text": "父・馬超ゆずりの馬の腕で、馬承は若い騎兵たちを鍛えた。走る隊列は、かつての西涼の騎兵のようだった。", "quote": "馬の上なら、父にも負けぬつもりです", "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "経歴にもとづく創作"},
  {"name": "劉永", "title": "へつらいを嫌う", "text": "劉永は、主君のお気に入りの宦官・黄皓をきらい、決して仲良くしなかった。そのため悪口を言われ、主君から遠ざけられてしまった。", "quote": "こびる者と並ぶくらいなら、遠ざけられるほうがましだ", "cond": [{"t": "with", "who": "劉禅"}], "fx": [{"t": "loyalty", "v": -10}], "src": "正史・劉永伝"},
  {"name": "劉理", "title": "兄を支えて", "text": "劉理は兄・劉禅を支え、治める土地の田畑を見て回っては、民の暮らしに心をくだいた。", "quote": "兄上の国の民が、腹をすかせぬように", "cond": [{"t": "with", "who": "劉禅"}], "fx": [{"t": "city", "k": "food", "v": 3000}, {"t": "stat", "k": "pol", "v": 1}], "src": "経歴にもとづく創作"},
  {"name": "劉諶", "title": "最後まで戦おう", "text": "敵が都にせまり、降伏の声が強まる中、劉諶は「最後まで戦うべきです」と父・劉禅にうったえた。その熱い心に、家臣たちもふるい立った。", "quote": "祖父の築いた国を、戦わずに渡せましょうか", "cond": [{"t": "with", "who": "劉禅"}], "fx": [{"t": "gens_loyalty", "v": 6}, {"t": "all", "k": "train", "v": 5}], "src": "正史・後主伝の裴注/演義第118回"},
  {"name": "劉璿", "title": "太子の心がまえ", "text": "太子の劉璿は馬に乗って弓を射るのが大好きで、勝手に出歩いてばかりいた。守り役の霍弋が昔の教えを引いて真心からいさめると、劉璿は行いを改めた。", "quote": "霍弋の言葉、胸にしみた。これからは気をつけよう。", "cond": [{"t": "with", "who": "霍弋"}], "fx": [{"t": "stat", "k": "pol", "v": 2}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・霍峻伝附霍弋伝"},
  {"name": "霍弋", "title": "南中を守る", "text": "南の国ざかいで暮らす人々がさわぎを起こした。霍弋は兵をひきいてしずめ、そのあとは土地の人々をいたわって、国ざかいを落ち着かせた。", "quote": "力でおさえるだけでなく、心をつかむのだ。", "cond": [{"t": "owns", "city": "建寧"}], "fx": [{"t": "city", "k": "loyal", "v": 8}, {"t": "city", "k": "def", "v": 100}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・霍弋伝（永昌・南中での統治）"},
  {"name": "王訓", "title": "父のように", "text": "王訓は、読み書きは苦手でも兵をまとめるのが上手だった父・王平にならい、兵士と同じものを食べ、いっしょに汗を流して訓練にはげんだ。", "quote": "父上は兵とともにあった。わしもそうするまで。", "cond": [{"t": "year_ge", "y": 248}], "fx": [{"t": "city", "k": "train", "v": 6}, {"t": "stat", "k": "lead", "v": 1}], "src": "経歴にもとづく創作（王平の子・後継）"},
  {"name": "蒋斌", "title": "敵も感心した返事", "text": "敵の将・鍾会から、亡き蒋琬の墓にお参りしたいという手紙がとどいた。蒋斌が礼儀正しく心のこもった返事を書くと、鍾会はその人がらに深く感心した。", "quote": "父の墓を敬ってくださるなら、喜んでお教えしましょう。", "cond": [{"t": "foe", "who": "鍾会"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "foe_city", "k": "train", "v": -4}], "src": "正史・蒋琬伝附蒋斌伝"},
  {"name": "蒋顕", "title": "太子のそばで", "text": "蒋顕は父・蒋琬ゆずりのおだやかな人がらで、太子のそばに仕えてまじめに務めた。その落ち着いた助言に、まわりの役人たちも耳をかたむけた。", "quote": "あわてず、まず人の話を聞くことです。", "cond": [{"t": "with", "who": "蒋斌"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "gens_loyalty", "v": 3}], "src": "経歴にもとづく創作（蒋琬の子・太子に仕える）"},
  {"name": "費恭", "title": "父の客をもてなす", "text": "費恭の家には、父・費禕をしたう人々がよく集まった。費恭は父と同じように分けへだてなくもてなし、たくさんの人と仲良くなった。", "quote": "父上のように、来る人をこばまぬようにしたいのです。", "cond": [{"t": "with", "who": "費禕"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "recruit", "n": 1}], "src": "経歴にもとづく創作（費禕の子）"},
  {"name": "龐宏", "title": "まっすぐな人", "text": "龐宏は飾らずまっすぐで、思ったことをはっきり言う人だった。力のある者にもこびずに正しいことを申し出たので、苦労は多かったが、正直な人々からはしたわれた。", "quote": "まちがっていることは、まちがっていると言うまでです。", "cond": [], "fx": [{"t": "stat", "k": "pol", "v": 2}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・龐統伝（龐宏は剛簡で陳祗を軽んじた）"},
  {"name": "李豊", "title": "父のぶんまで", "text": "父の李厳がしくじって役を外されたあとも、李豊はくさらずに働きつづけた。諸葛亮はその姿を見て、これからも力をつくしてほしいとはげました。", "quote": "父のあやまちは、わたしの働きでつぐないます。", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "city", "k": "food", "v": 3000}], "src": "経歴にもとづく創作（李厳の子・李厳失脚後も蜀に仕える）"},
  {"name": "孫登", "title": "とんできた弾", "text": "孫登が馬で出かけた時、弾が飛んできた。弾弓を持つ男がつかまり、家来はたたこうとしたが、孫登は止めて本当の弾を探させた。くらべると違うと分かり、男は許された。", "quote": "疑わしいだけで人を打ってはならぬ。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "city", "k": "loyal", "v": 8}], "src": "正史・孫登伝注（呉書）"},
  {"name": "孫和", "title": "遊びより大事なこと", "text": "役人たちの間で盤のゲームがはやり、仕事をおろそかにする者が出てきた。孫和がこれを心配すると、韋昭が論を書いてさし出し、孫和はそれを家来たちに配った。", "quote": "時を大切にし、もっと役に立つことに使おう。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "pol", "v": 1}, {"t": "gens_loyalty", "v": 4}], "src": "正史・孫和伝（韋曜「博弈論」）"},
  {"name": "孫覇", "title": "太子の座をねらう", "text": "孫覇は兄の孫和に代わって跡つぎになろうと、なかまの家来を集め始めた。宮中は二つに分かれて争い、家来たちの心も落ち着かなくなった。", "quote": "わしこそ跡つぎにふさわしい。だれがわしにつく。", "cond": [{"t": "with", "who": "孫和"}, {"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "gens_loyalty", "v": -4}, {"t": "loyalty", "v": -10}], "src": "正史・孫覇伝（二宮の変）"},
  {"name": "孫亮", "title": "はちみつのなぞ", "text": "孫亮のはちみつにネズミのふんが入っていた。係の者は自分のせいにされそうになったが、孫亮はふんを割らせ、中が乾いているので後から入れたと見ぬいた。犯人は罪をみとめた。", "quote": "ふんの中まで湿っていなければ、後から入れたものだ。", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・孫亮伝注（呉歴）"},
  {"name": "孫休", "title": "臘の日の計略", "text": "大きな力を持つ孫綝に悩んだ孫休は、丁奉とひそかに計画を練った。臘の日の宴の席で孫綝をとらえ、国の力を取りもどした。", "quote": "丁奉よ、そなたの知恵と勇気がたよりだ。", "cond": [{"t": "with", "who": "丁奉"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "loyalty", "v": 10, "who": "丁奉"}, {"t": "all", "k": "loyal", "v": 5}], "src": "正史・孫休伝、丁奉伝"},
  {"name": "孫魯班", "title": "ひそひそ話", "text": "孫魯班は、孫和の母のことを父の孫権に何度も悪く言った。孫権はそれを信じて怒り、孫和は父の気に入られなくなってしまった。", "quote": "父上、あの人は父上のご病気を喜んでおりましたよ。", "cond": [{"t": "with", "who": "孫和"}, {"t": "lord", "who": "孫権"}], "fx": [{"t": "loyalty", "v": -12, "who": "孫和"}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・孫和伝、妃嬪伝"},
  {"name": "孫紹", "title": "小覇王の子", "text": "孫紹は、江東を切り開いた父・孫策の話を聞いて育った。父に負けないようにと武芸にはげむ姿に、古くからの家来たちは昔を思い出して目をうるませた。", "quote": "父上の名に恥じぬ男になってみせます。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "gens_loyalty", "v": 3}], "src": "経歴にもとづく創作（孫策の子）"},
  {"name": "周循", "title": "父ゆずりの音", "text": "周循は「父・周瑜の面影がある」と言われ、孫権の娘をめとった。宴でその姿を見た孫権は、亡き周瑜をしのんで目を細めた。", "quote": "父の名に恥じぬよう、つとめてまいります。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "cha", "v": 2}, {"t": "loyalty", "v": 10}], "src": "経歴にもとづく創作（周瑜の子・孫魯班を妻とする）"},
  {"name": "周胤", "title": "許された罪", "text": "周胤は罪をおかして遠くへ追いやられた。諸葛瑾たちが、周瑜の手がらを思ってどうか許してほしいと願い出ると、孫権は迷ったすえに罰を取り消した。", "quote": "みなさまの恩、けっして忘れませぬ。", "cond": [{"t": "with", "who": "諸葛瑾"}, {"t": "lord", "who": "孫権"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "war", "v": -1}], "src": "正史・周瑜伝"},
  {"name": "魯淑", "title": "きちんとした守り", "text": "守りの役についた魯淑は、兵のきまりや城の手入れをきちんと整えた。どこへ行っても乱れがないので、まわりの人々は安心してくらせた。", "quote": "小さなゆるみが、大きなほころびになるのです。", "cond": [], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作（魯粛の子・呉の将）"},
  {"name": "呂霸", "title": "父の教え", "text": "呂霸は、若いころは学問をしなかったが後に猛勉強した父・呂蒙の話を思い出し、自分も本を手に取った。ひまを見つけては兵法を学んだ。", "quote": "父上も学んで変わったのだ。わしも負けぬ。", "cond": [], "fx": [{"t": "stat", "k": "int", "v": 2}], "src": "経歴にもとづく創作（呂蒙の子・呉下の阿蒙の故事）"},
  {"name": "凌烈", "title": "わが虎の子", "text": "父の凌統が亡くなったあと、孫権は幼い凌烈と弟を宮中で自分の子のように育てた。客が来ると二人を呼び、これがわしの虎の子だと自慢した。", "quote": "殿の虎の子として、父に負けぬ働きをいたします。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "war", "v": 1}], "src": "正史・凌統伝"},
  {"name": "凌封", "title": "馬の稽古", "text": "凌封は兄とともに学問を教わり、決まった日には馬の稽古もした。やがて父の兵をまかされると、父ゆずりの勇ましさで兵たちを引っぱった。", "quote": "父上の兵、わたしがしっかりあずかります。", "cond": [{"t": "lord", "who": "孫権"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "正史・凌統伝（葛光に学び、兄の後に兵を継ぐ）"},
  {"name": "黄柄", "title": "苦肉の計の子", "text": "黄柄は、体を張って赤壁の勝利を助けた父・黄蓋の話をよく聞かされた。父のように国のため身をささげようと、兵たちと共に訓練にはげんだ。", "quote": "父上のように、いざという時に命をかけられる者に。", "cond": [], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "loyalty", "v": 10}], "src": "経歴にもとづく創作（黄蓋の子）"},
  {"name": "程咨", "title": "古株の子", "text": "程咨は、孫堅のころから仕えた古株の父・程普をほこりにしていた。若い将たちにも親切に声をかけ、父のように皆から頼られる人になろうと努めた。", "quote": "父上は皆に慕われた。わしもそうありたい。", "cond": [], "fx": [{"t": "stat", "k": "cha", "v": 1}, {"t": "gens_loyalty", "v": 3}], "src": "経歴にもとづく創作（程普の子）"},
  {"name": "朱績", "title": "引く敵を追え", "text": "魏の軍が江陵をせめたが落とせず引きあげていった。朱績は、今こそ追いうちの時と見て、なかまに助けを求めたうえで自ら兵をひきいて追いかけた。", "quote": "引く敵こそ、うつべき時。おくれるな。", "cond": [{"t": "owns", "city": "江陵"}], "fx": [{"t": "foe_city", "k": "train", "v": -6}, {"t": "stat", "k": "lead", "v": 1}], "src": "正史・朱然伝附朱績伝"},
  {"name": "朱異", "title": "七つの陣を破る", "text": "魏の文欽の軍がとりでをならべて守っていた。朱異は兵をひきいておそいかかり、七つの陣を打ち破って、敵を大いにあわてさせた。", "quote": "陣がいくつあろうと、ひとつずつ破るまでよ。", "cond": [{"t": "foe", "who": "文欽"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -8}], "src": "正史・朱桓伝附朱異伝"},
  {"name": "全懌", "title": "にせの手紙", "text": "一族の者から、ご主君がひどく怒っていて戻れば罰せられるという手紙がとどいた。じつは鍾会の計略だったが、全懌はおそれて心がゆれてしまった。", "quote": "帰れば罰か……このままでは身があぶない。", "cond": [{"t": "foe", "who": "鍾会"}], "fx": [{"t": "loyalty", "v": -20}], "src": "正史・全琮伝、諸葛誕伝（鍾会の計）"},
  {"name": "張承", "title": "人を見る目", "text": "若い諸葛恪は才能があると皆にほめられていた。しかし張承は、このままでは一族をあやうくすると心配し、まわりにも気をつけるよう話した。", "quote": "才があまって、慎みが足りぬ。それが心配なのだ。", "cond": [{"t": "with", "who": "諸葛恪"}], "fx": [{"t": "stat", "k": "int", "v": 1}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・張昭伝附張承伝"},
  {"name": "張休", "title": "太子に漢書を", "text": "張休は太子の孫登のそばに仕え、歴史の書『漢書』を読んで聞かせた。太子は熱心に耳をかたむけ、二人はますます心を通わせた。", "quote": "昔の人の成功と失敗こそ、殿下の一番の先生です", "cond": [{"t": "with", "who": "孫登"}], "fx": [{"t": "stat", "k": "int", "v": 1, "who": "孫登"}, {"t": "loyalty", "v": 10}], "src": "正史・張昭伝附張休伝（孫登に漢書を授ける）"},
  {"name": "諸葛融", "title": "公安の狩りと宴", "text": "諸葛融は公安の兵をあずかり、秋と冬は狩りで兵をきたえ、春と夏はうたげを開いてみなをもてなした。兵たちは大いに喜び、よくなついた。", "quote": "きたえる時はきたえ、楽しむ時は楽しもうぞ", "cond": [{"t": "year_ge", "y": 241}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "city", "k": "loyal", "v": 5}, {"t": "stat", "k": "cha", "v": 1}], "src": "正史・諸葛瑾伝附諸葛融伝（公安で狩猟と宴を行う）"},
  {"name": "甘瓌", "title": "父の背中を追う", "text": "甘瓌は、川で名をあげた父・甘寧の話を思い出し、自分も強い将になろうと、朝から晩まで船の上で兵とともに汗を流した。", "quote": "父上に負けぬ働きを、この手で見せてやる", "cond": [], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 5}], "src": "経歴にもとづく創作（甘寧の子）"},
  {"name": "陸景", "title": "父の教え、筆に託す", "text": "陸景は父・陸抗のもとで学問にはげみ、昼は兵を見回り、夜は灯りの下で書を書きつづけた。その文章は多くの人に読まれた。", "quote": "父上の教えを、のちの世まで残したいのです", "cond": [{"t": "with", "who": "陸抗"}], "fx": [{"t": "stat", "k": "int", "v": 2}, {"t": "stat", "k": "pol", "v": 1}], "src": "正史・陸抗伝注（学問を好み書数十篇を著す）"},
  {"name": "潘鳳", "title": "わが上将潘鳳", "text": "主君の韓馥は「わしには上将の潘鳳がいる」と胸を張った。大きな斧をかついだ潘鳳が進み出ると、兵たちは「さすがだ」と声をあげた。", "quote": "この大斧にかけて、殿の期待にこたえてみせよう", "cond": [{"t": "lord", "who": "韓馥"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "loyalty", "v": 10}], "src": "演義第5回（韓馥が上将潘鳳を推す）"},
  {"name": "武安国", "title": "鉄鎚の猛将", "text": "孔融に仕える武安国は、重い鉄のつちを軽々と振り回し、あの呂布にもおそれず立ち向かった。その勇気に、北海の兵たちは奮い立った。", "quote": "相手が誰であろうと、引き下がるわしではない", "cond": [{"t": "lord", "who": "孔融"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 6}], "src": "演義第5回（孔融の将、鉄鎚で呂布と戦う）"},
  {"name": "兪渉", "title": "真っ先に名乗る", "text": "強い敵が門の前で暴れていると聞くと、兪渉は「わたしが行きます」と真っ先に手をあげた。その勢いに、陣の中は大いにわいた。", "quote": "わたしが出ます！みな、見ておれ！", "cond": [{"t": "lord", "who": "袁術"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "loyalty", "v": 8}], "src": "演義第5回（袁術の将、華雄に挑む）"},
  {"name": "方悦", "title": "河内の騎馬", "text": "方悦は馬の扱いがうまく、毎朝、騎兵たちと野を駆けまわった。兵たちは方悦について走るうちに、すっかり馬になれていった。", "quote": "馬と心をひとつにすれば、どこまでも駆けられる", "cond": [], "fx": [{"t": "city", "k": "train", "v": 6}, {"t": "stat", "k": "lead", "v": 1}], "src": "演義第5回の人物像（王匡の将・騎馬）にもとづく創作"},
  {"name": "穆順", "title": "張楊の先がけ", "text": "穆順は主君の張楊のために、いつも先頭に立って敵に突っこんでいった。そのむこうみずな勇気に、兵たちも負けじと続いた。", "quote": "殿の前に道をひらくのは、この穆順だ", "cond": [{"t": "lord", "who": "張楊"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第5回（張楊の将、呂布に挑む）"},
  {"name": "胡班", "title": "父の手紙", "text": "胡班は父・胡華からの手紙を受け取り、関羽がどれほど立派な人かを知った。胡班は関羽の危機を救い、それからは関羽を心から慕って仕えた。", "quote": "関将軍のためなら、この命も惜しくありません", "cond": [{"t": "with", "who": "関羽"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "cha", "v": 1}], "src": "演義第27回（父胡華の手紙、関羽に王植の火計を知らせる）"},
  {"name": "卞喜", "title": "汜水関の備え", "text": "汜水関を守る卞喜は、人目につかない場所に兵をひそませる工夫を重ねた。関所の守りはいっそう固くなった。", "quote": "敵が来たら、思いもよらぬところから迎えてやる", "cond": [], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "stat", "k": "int", "v": 1}], "src": "演義第27回（汜水関の守将、伏兵を置く）にもとづく創作"},
  {"name": "孔秀", "title": "東嶺関の門番", "text": "東嶺関を守る孔秀は、通る者を一人ひとりきびしく調べた。あやしい者は一人も通さず、町の人たちは安心してくらせた。", "quote": "決まりは決まり。だれであろうと調べさせてもらう", "cond": [], "fx": [{"t": "city", "k": "def", "v": 80}, {"t": "city", "k": "loyal", "v": 4}], "src": "演義第27回（東嶺関の守将）にもとづく創作"},
  {"name": "韓福", "title": "洛陽の守り", "text": "洛陽をあずかる韓福は、用心深く城のまわりを見回り、守りの弱いところを一つずつ直していった。", "quote": "油断こそ一番の敵。念には念を入れよ", "cond": [{"t": "owns", "city": "洛陽"}], "fx": [{"t": "city", "k": "def", "v": 120}, {"t": "stat", "k": "pol", "v": 1}], "src": "演義第27回（洛陽太守、慎重な守将）にもとづく創作"},
  {"name": "孟坦", "title": "韓福の右腕", "text": "孟坦は主将の韓福のもとで、兵を連れて城の外を見回った。韓福は孟坦の働きをほめ、二人の息はぴったり合っていった。", "quote": "韓福どの、外の見張りはおまかせを", "cond": [{"t": "with", "who": "韓福"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "loyalty", "v": 10}], "src": "演義第27回（韓福の部将）にもとづく創作"},
  {"name": "秦琪", "title": "黄河の渡し守", "text": "秦琪は黄河の渡し場を守り、船と兵をしっかり見張った。おじの蔡陽は、甥の働きぶりを聞いて大いに喜んだ。", "quote": "おじ上の名に恥じぬよう、この渡しは守りぬく", "cond": [{"t": "with", "who": "蔡陽"}], "fx": [{"t": "city", "k": "def", "v": 80}, {"t": "loyalty", "v": 10}], "src": "演義第27～28回（黄河渡口の守将、蔡陽の甥）"},
  {"name": "蔡陽", "title": "老将の怒り", "text": "甥の秦琪が関羽に討たれたと聞き、蔡陽は怒りに燃えた。「必ずかたきを討つ」とちかい、兵たちをきびしくきたえ直した。", "quote": "関羽め、この蔡陽が相手になってやろう", "cond": [{"t": "foe", "who": "関羽"}], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第28回（甥秦琪の死で関羽を恨む）"},
  {"name": "夏侯恩", "title": "青釭の剣", "text": "曹操は、自分の宝の剣「青釭」を夏侯恩にあずけた。夏侯恩は剣を背負い、主君の信頼にこたえようと胸を張った。", "quote": "殿の宝剣、この身にかえてもお守りします", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第41回（曹操の青釭剣を預かる）"},
  {"name": "晏明", "title": "三つ又の刀", "text": "曹洪に仕える晏明は、三つに分かれた刃の刀を自在にあやつった。そのめずらしい技を見ようと、兵たちが集まって腕をみがいた。", "quote": "この刀をかわせる者は、そうはおらんぞ", "cond": [{"t": "with", "who": "曹洪"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "city", "k": "train", "v": 5}], "src": "演義第41回（曹洪の部将、三尖両刃刀の使い手）"},
  {"name": "淳于導", "title": "手がらの生けどり", "text": "曹仁に仕える淳于導は、乱れた戦場で敵の糜竺を見つけ、なわでしばって連れ帰った。曹仁は大いにほめた。", "quote": "大物を捕らえましたぞ、曹仁さま！", "cond": [{"t": "with", "who": "曹仁"}, {"t": "foe", "who": "糜竺"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "foe_city", "k": "loyal", "v": -5}], "src": "演義第41回（曹仁の部将、糜竺を捕らえる）"},
  {"name": "韓浩", "title": "人質に屈せず", "text": "夏侯惇が悪者に捕まった時、韓浩はあわてる兵をしずめ、悪者たちに立ち向かって夏侯惇を救い出した。曹操はこの行いを、のちの手本にせよとほめた。", "quote": "人質を取られても、悪に屈してはならぬ", "cond": [{"t": "with", "who": "夏侯惇"}], "fx": [{"t": "stat", "k": "lead", "v": 1}, {"t": "loyalty", "v": 10, "who": "夏侯惇"}, {"t": "gens_loyalty", "v": 4}], "src": "正史・夏侯惇伝（韓浩が人質事件で夏侯惇を救う）"},
  {"name": "史渙", "title": "兵糧車を焼け", "text": "史渙は徐晃とともに、敵の兵糧を運ぶ車の列をおそい、すべて焼きはらった。食べ物を失った敵の陣は、すっかり元気をなくした。", "quote": "腹がへっては戦はできぬ。敵の米を断て！", "cond": [{"t": "with", "who": "徐晃"}], "fx": [{"t": "foe_city", "k": "train", "v": -6}, {"t": "stat", "k": "war", "v": 1}], "src": "正史・武帝紀（官渡で徐晃・史渙が韓猛の輜重を焼く）"},
  {"name": "王忠", "title": "関羽の情け", "text": "王忠は劉備をせめに行ったが、関羽に捕らえられてしまった。ところが関羽は王忠を手あつくもてなして帰した。王忠の心は少しゆれた。", "quote": "敵の将に情けをかけられるとは……", "cond": [{"t": "foe", "who": "関羽"}], "fx": [{"t": "loyalty", "v": -10}, {"t": "stat", "k": "int", "v": 1}], "src": "正史・武帝紀（劉備討伐に失敗）／演義（関羽に捕らえられ放される）"},
  {"name": "車冑", "title": "徐州をあずかる", "text": "車冑は曹操から徐州をまかされ、下邳の城でまつりごとにはげんだ。城の守りを固め、町の人びとの声にも耳をかたむけた。", "quote": "曹公の名代として、この地をしっかり治めねば", "cond": [{"t": "lord", "who": "曹操"}, {"t": "owns", "city": "下邳"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "city", "k": "loyal", "v": 4}], "src": "正史・先主伝（曹操が置いた徐州刺史）にもとづく創作"},
  {"name": "曹性", "title": "ねらいすました一矢", "text": "曹性は高順とともに戦い、遠くから弓をひきしぼって敵将をねらい打った。思わぬ矢に敵の陣はおおいに乱れた。", "quote": "この弓で、遠くの敵も逃がしはせぬ", "cond": [{"t": "with", "who": "高順"}], "fx": [{"t": "stat", "k": "war", "v": 1}, {"t": "foe_city", "k": "train", "v": -5}], "src": "演義第18回（高順の部下、夏侯惇の目を射る）"},
  {"name": "宋憲", "title": "仲間をかばう", "text": "侯成が呂布の怒りを買ってむち打たれそうになった時、宋憲は進み出て、ゆるしてくれるよう必死にたのんだ。侯成はこの恩を忘れなかった。", "quote": "殿、どうか侯成をおゆるしください", "cond": [{"t": "with", "who": "侯成"}], "fx": [{"t": "loyalty", "v": 10, "who": "侯成"}, {"t": "stat", "k": "cha", "v": 1}], "src": "演義第19回（宋憲・魏続が侯成の命ごいをする）"},
  {"name": "魏続", "title": "さめていく心", "text": "下邳の城に閉じこめられる日々が続き、魏続は呂布のやり方に不満をつのらせた。宋憲や侯成とひそひそ話をすることが増えていった。", "quote": "このまま殿について行って、よいものか……", "cond": [{"t": "lord", "who": "呂布"}, {"t": "with", "who": "侯成"}], "fx": [{"t": "loyalty", "v": -15}], "src": "正史・呂布伝／演義第19回（侯成・宋憲と共に呂布にそむく）"},
  {"name": "侯成", "title": "お祝いの酒", "text": "侯成は盗まれた馬を取り返し、仲間とお祝いしようと呂布にも酒をとどけた。ところが酒を禁じていた呂布は大いに怒り、侯成はすっかり落ちこんだ。", "quote": "よかれと思ってしたことが、こんなことに……", "cond": [{"t": "lord", "who": "呂布"}], "fx": [{"t": "loyalty", "v": -15}], "src": "正史・呂布伝注／演義第19回（馬を取り返して酒を献じ呂布の怒りを買う）"},
  {"name": "郝萌", "title": "夜にゆれる野心", "text": "袁術からひそかに手紙がとどき、郝萌の心はゆれた。夜に兵を集めて呂布にそむこうとしたが、仲間に気づかれて思いとどまった。", "quote": "呂布の下にいて、わしは一生このままなのか……", "cond": [{"t": "with", "who": "呂布"}, {"t": "foe", "who": "袁術"}], "fx": [{"t": "loyalty", "v": -15}, {"t": "city", "k": "loyal", "v": -4}], "src": "正史・呂布伝注『英雄記』（郝萌の反乱）"},
  {"name": "成廉", "title": "赤兎とともに", "text": "成廉は呂布の赤兎馬のすぐ後ろにつき、敵の陣へ何度もつっこんだ。そのたびに手がらを立てて帰り、兵たちは大いにふるい立った。", "quote": "殿の背中から、はなれはせぬ！", "cond": [{"t": "with", "who": "呂布"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 6}], "src": "正史・呂布伝注（張燕との戦いで呂布と成廉・魏越が敵陣に突入）"},
  {"name": "張闓", "title": "宝に目がくらむ", "text": "大事な客を送りとどける役をまかされた張闓。ところが荷物の宝に目がくらみ、金をうばって姿をくらましてしまった。", "quote": "これだけの宝があれば、一生遊んで暮らせるぞ", "cond": [], "fx": [{"t": "city", "k": "gold", "v": -500}, {"t": "loyalty", "v": -15}], "src": "正史・武帝紀注『呉書』／演義第10回（曹嵩殺害）"},
  {"name": "雷薄", "title": "閉ざした門", "text": "落ちぶれた昔の主・袁術が、助けてほしいと雷薄をたずねてきた。雷薄は陳蘭とともに門を閉ざし、今の主に仕える覚悟を決めた。", "quote": "わがままな主のために、もう兵は死なせぬ", "cond": [{"t": "foe", "who": "袁術"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "city", "k": "loyal", "v": 5}], "src": "正史・袁術伝（灊山の雷薄・陳蘭が袁術を受け入れず）"},
  {"name": "陳蘭", "title": "山のとりで", "text": "陳蘭はけわしい山にとりでを築いて立てこもるのが得意だった。その知恵を生かし、城のまわりの守りを山のように固めた。", "quote": "山を味方にすれば、大軍もこわくはない", "cond": [], "fx": [{"t": "city", "k": "def", "v": 120}], "src": "正史・張遼伝（陳蘭が灊山に拠って抵抗）"},
  {"name": "楊醜", "title": "強い者になびく", "text": "曹操の勢いがますます強いと聞き、楊醜の心はそちらへかたむいた。主のそばにいながら、裏で曹操と手を結ぶことばかり考えている。", "quote": "勝つ方につく。それが生きのびる道よ", "cond": [{"t": "foe", "who": "曹操"}], "fx": [{"t": "loyalty", "v": -15}], "src": "正史・張楊伝（楊醜が張楊を殺し曹操に降ろうとした）"},
  {"name": "眭固", "title": "裏切りを討つ", "text": "張楊の陣で、主にそむこうとたくらむ者がいた。眭固はいち早く気づいて討ち、張楊の兵をまとめ直した。", "quote": "主を売るようなやつは、この眭固が許さん", "cond": [{"t": "lord", "who": "張楊"}], "fx": [{"t": "loyalty", "v": 15}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・張楊伝（眭固が楊醜を殺し、張楊の兵を引き継ぐ）"},
  {"name": "梁興", "title": "あらしの騎馬隊", "text": "梁興は騎馬隊をひきいて、となりの敵の土地をかけまわった。役人たちはおびえ、敵の村々はすっかり落ち着きをなくした。", "quote": "関中の風のように、来ては去るのみよ", "cond": [], "fx": [{"t": "foe_city", "k": "loyal", "v": -6}, {"t": "stat", "k": "war", "v": 1}], "src": "正史・夏侯淵伝（潼関の敗戦後、梁興が左馮翊を荒らす）"},
  {"name": "成宜", "title": "呼びかけに応ず", "text": "馬超が兵を挙げると聞き、成宜は関中の騎馬兵を連れてかけつけた。二人は馬を並べて、ともに戦うことをちかった。", "quote": "西の男は、一度決めたら引きはせぬ", "cond": [{"t": "with", "who": "馬超"}], "fx": [{"t": "loyalty", "v": 10}, {"t": "city", "k": "train", "v": 6}], "src": "正史・武帝紀（関中十部の一人として馬超・韓遂と挙兵）"},
  {"name": "侯選", "title": "関中の道案内", "text": "関中の地を知りつくした侯選が、山や川の間をぬける騎馬の通り道を味方に教えた。兵たちは思うままに動けるようになった。", "quote": "この辺りの道なら、目をつぶっても走れますぞ", "cond": [{"t": "with", "who": "韓遂"}], "fx": [{"t": "city", "k": "train", "v": 5}, {"t": "stat", "k": "lead", "v": 1}], "src": "経歴にもとづく創作（関中十部の一人）"},
  {"name": "程銀", "title": "関中の仲間集め", "text": "程銀が古い仲間に声をかけると、関中の荒っぽい騎馬の男たちが次々と集まってきた。", "quote": "腕に自信のあるやつは、わしについて来い！", "cond": [], "fx": [{"t": "city", "k": "troops", "v": 2000}], "src": "経歴にもとづく創作（関中十部の一人）"},
  {"name": "李堪", "title": "潼関の先陣", "text": "曹操の大軍が近づくと、李堪は先頭に立って馬を走らせた。その勇ましい姿に、まわりの兵も負けじと続いた。", "quote": "曹操の旗を、この手で引きたおしてくれる！", "cond": [{"t": "with", "who": "馬超"}, {"t": "foe", "who": "曹操"}], "fx": [{"t": "stat", "k": "war", "v": 2}, {"t": "city", "k": "train", "v": 4}], "src": "正史・武帝紀（関中十部として潼関で曹操と戦う）"},
  {"name": "馬玩", "title": "二人の間に立つ", "text": "韓遂と馬超の仲が、敵の手紙のせいでぎくしゃくしはじめた。馬玩は二人の間に入り、敵のわなだと説いて仲直りさせた。", "quote": "仲間割れこそ、敵の思うつぼですぞ", "cond": [{"t": "with", "who": "韓遂"}, {"t": "with", "who": "馬超"}], "fx": [{"t": "loyalty", "who": "馬超", "v": 10}, {"t": "loyalty", "who": "韓遂", "v": 10}], "src": "演義第59回（曹操の離間策で韓遂と馬超が対立）"},
  {"name": "張横", "title": "騎馬のきたえ方", "text": "張横は、馬に乗ったまま弓を引く西の戦い方を、味方の兵たちに一からきたえこんだ。", "quote": "馬と一つになれ。それが関中の戦いだ", "cond": [], "fx": [{"t": "all", "k": "train", "v": 4}], "src": "経歴にもとづく創作（関中十部の一人）"},
  {"name": "楊秋", "title": "ゆるされた恩", "text": "降ってきた楊秋を、主はもとの地位のまま安定の守りにつかせた。楊秋はその恩にこたえ、西の守りを固めた。", "quote": "この恩、西の守りでお返しいたします", "cond": [{"t": "lord", "who": "曹操"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "city", "k": "def", "v": 100}], "src": "正史・夏侯淵伝ほか（楊秋が安定で降り、元の官爵を許される）"},
  {"name": "金環三結", "title": "三洞の元帥", "text": "孟獲は金環三結を三つの洞の元帥の一人に選んだ。金環三結は南の勇ましい兵を集め、大軍をととのえた。", "quote": "大王のため、この金環三結が先頭を行く！", "cond": [{"t": "lord", "who": "孟獲"}], "fx": [{"t": "city", "k": "troops", "v": 3000}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第87回（三洞元帥の一人）"},
  {"name": "董荼那", "title": "忘れられぬ恩", "text": "一度とらえられた時、諸葛亮は董荼那をやさしくはげまし、放してくれた。その恩が忘れられず、孟獲のために戦う気持ちがうすれてしまった。", "quote": "あのお方と、また戦えというのか……", "cond": [{"t": "lord", "who": "孟獲"}, {"t": "foe", "who": "諸葛亮"}], "fx": [{"t": "loyalty", "v": -20}], "src": "演義第87・88回（諸葛亮に放され、のち孟獲を縛って差し出す）"},
  {"name": "阿会喃", "title": "心からの誓い", "text": "命を助けられた阿会喃は、諸葛亮の情けの深さに心を打たれた。今度こそ、このお方のために働こうとかたく誓った。", "quote": "情けをかけられた命、あなたにささげます", "cond": [{"t": "with", "who": "諸葛亮"}], "fx": [{"t": "loyalty", "v": 25}], "src": "演義第87・88回（とらえられて諸葛亮に放される）"},
  {"name": "朶思大王", "title": "毒の泉の守り", "text": "朶思大王の住む洞へは、毒の泉がわく道しかない。朶思大王はその地の知恵を使い、敵が近づけない守りを作り上げた。", "quote": "この泉の水を飲めば、どんな兵もおしまいよ", "cond": [{"t": "with", "who": "孟獲"}], "fx": [{"t": "city", "k": "def", "v": 150}, {"t": "stat", "k": "int", "v": 1}], "src": "演義第89回（禿龍洞と毒の泉）"},
  {"name": "木鹿大王", "title": "けものの軍団", "text": "木鹿大王が鐘を鳴らすと、虎やひょう、大きな象が集まってきた。けものたちを兵とともに戦えるよう、しっかりしこんだ。", "quote": "わしの獣たちにかなう軍などあるものか！", "cond": [{"t": "with", "who": "孟獲"}], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "stat", "k": "war", "v": 1}], "src": "演義第90回（猛獣を操って蜀軍と戦う）"},
  {"name": "帯来洞主", "title": "助っ人を呼ぶ", "text": "負けが続いて元気のない義兄・孟獲に、帯来洞主は南の遠い地にいる強い仲間を呼ぼうと言い出し、自ら迎えに出かけた。", "quote": "義兄上、わしに心当たりがございます", "cond": [{"t": "with", "who": "孟獲"}], "fx": [{"t": "recruit", "n": 1}, {"t": "loyalty", "v": 10}], "src": "演義第90回（木鹿大王を推挙する）"},
  {"name": "越吉", "title": "鉄の戦車隊", "text": "越吉は、鉄の板で固めた戦車をつなげて走らせる羌の兵をひきいていた。その戦車がうなりを上げると、兵たちの勢いはいっそう強まった。", "quote": "鉄の車の前に、立ちふさがれる者はおらぬ！", "cond": [], "fx": [{"t": "city", "k": "train", "v": 8}, {"t": "city", "k": "def", "v": 60}], "src": "演義第94回（羌の鉄車兵）"},
  {"name": "周昕", "title": "故郷を守る", "text": "会稽生まれの周昕は、ふるさとに迫る敵を前に王朗を助けて兵を出した。人々も周昕を信じて力を合わせた。", "quote": "ふるさとの民を、見捨てるわけにはまいらぬ", "cond": [{"t": "with", "who": "王朗"}, {"t": "foe", "who": "孫策"}], "fx": [{"t": "city", "k": "def", "v": 100}, {"t": "city", "k": "loyal", "v": 6}], "src": "正史・孫策伝注（王朗を助けて孫策に抵抗）"},
  {"name": "祖茂", "title": "赤い頭巾", "text": "敵に追われた孫堅は、目立つ赤い頭巾を祖茂にあずけた。祖茂がそれをかぶって敵を引きつけ、孫堅は無事に逃げのびた。", "quote": "殿の身代わりなら、喜んで引き受けましょう", "cond": [{"t": "lord", "who": "孫堅"}], "fx": [{"t": "loyalty", "v": 20}, {"t": "stat", "k": "war", "v": 1}], "src": "正史・孫堅伝（徐栄に敗れた際、赤い頭巾で敵を引きつける）"},
  {"name": "吾粲", "title": "あらしの船", "text": "大あらしで船が流され、兵たちが海に投げ出された。吾粲は船が重くなるのもかまわず、おぼれる兵を次々と引き上げた。", "quote": "船が沈むなら、皆いっしょだ。さあ、つかまれ！", "cond": [], "fx": [{"t": "city", "k": "loyal", "v": 8}, {"t": "stat", "k": "cha", "v": 2}], "src": "正史・吾粲伝（洞口の戦いの暴風で溺れる兵を救う）"}
];
